local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.greeting
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.greeting = text
end
local rows = text.templates
rows[#rows+1]={"$964w, young $c.","$964w 명이네. 젊은 $c|1이여;여;..."}
rows[#rows+1]={"$966w, young $c.","젊은 $c|1이여;여;, $966w명이 살아있군."}
rows[#rows+1]={"$C, Dame Auriferous has conveyed to me her great pleasure in the service that you have done us in the past. She wishes to extend to you her hope that you will continue to be a champion of sin'dorei interests here in the Ghostlands.","귀부인 아우리페러스께서 지난번에 우리 일을 도와줘서 매우 고맙다는 뜻을 그대에 전하라고 하셨습니다. 그리고 그대가 계속해서 이곳 유령의 땅에서 신도레이를 지켜주기를 바라십니다."}
rows[#rows+1]={"$C, I need more copper bars! There's a war brewing at the Gates of Ahn'Qiraj and we need supplies! The Alliance has collected $1997w and we need $1998w copper bars in total. If I don't get those copper bars, it's going to be my head on a platter!","구리 주괴가 더 필요합니다! 안퀴라즈 성문 앞에 전쟁의 열기가 끓어가고 있는 상황에서 전쟁 물자를 비축해야 합니다. 지금까지 얼라이언스 연합에서 모은 것은 $1997w개인데 우리에게 필요한 것은 모두 $1998w개입니다. 구리 주괴를 다 모으지 못하면 제가 혼이 날지도 몰라요."}
rows[#rows+1]={"$C, back on Azeroth, the Silverwing Sentinels hamper our progress in the woods. We need you there on the battlefront to push them back! You will earn great honor and reputation with the Warsong Outriders for helping us - join us now!","$C 친구, 아제로스의 숲에서 진행 중인 우리 일을 은빛날개 파수대가 방해하고 있어. 자네가 가서 놈들을 몰아내 주게! 우리를 도와주면 전쟁노래 정찰대 사이에서 좋은 평판과 명예를 얻을 수 있을 걸세. 어서 동참하게!"}
rows[#rows+1]={"$C, eh? I am Krazek, Baron Revilgaz's secretary. I know everything about the goings on in this jungle and beyond. Perhaps you'd be interested in knowing the going price on oil in Ratchet? No? Looking for work, maybe? I can help you there.","$C인가? 나는 크라젝, 남작 레빌가즈의 비서라네. 이 밀림 안팎에서 돌아가는 일이라면 모르는 게 없지. 톱니항 기름 시세라도 궁금한가? 아니라고? 그럼 일거리라도 찾나? 그건 내가 도와줄 수 있지."}
rows[#rows+1]={"$C, even our hardiest warriors and scouts will need use of the healing arts in the war to come at Ahn'Qiraj. And when there is no magical healing available, they must rely upon our efforts here.$B$BTo date I have collected $2088w runecloth bandages, out of $2090w needed. If you are willing, we should speak further on how you can do your part.","우리 막강한 전사들과 정찰병들이 아무리 뛰어나다 해도 곧 있을 안퀴라즈 전쟁에서 부상을 전혀 입지 않을 수는 없소이다. 그리고 마법으로 치료할 상황이 안 된다면 우리가 여기서 만들고 있는 붕대에 전적으로 의존할 수밖에 없는 것이오.$B$B지금까지 $2088w개의 룬무늬 붕대를 모았는데 모두 $2090w개가 필요합니다. 원한다면 어느 정도 도와주실 수 있는지 말해주시기 바라오."}
rows[#rows+1]={"$C, hold your attack, this is just a disguise!  I'm a spy working for the Lower City coalition out of Shattrath City.$B$BI hope you're here to help!","공격을 멈추시오! 이건 변장일 뿐이오. 난 샤트라스 외부의 고난의 거리 연합 밑에서 일하는 비밀요원이요.$B$B당신의 도움이 필요하오!"}
rows[#rows+1]={"$C, look what they've done to our beloved land. The Scourge must be destroyed!","놈들이 소중한 우리 땅에서 무슨 짓을 저질렀는지 보세요. 스컬지는 반드시 해치워야 합니다!"}
rows[#rows+1]={"$C, please listen to what I have to say. The Alliance and Horde are preparing for a war with the Silithid and their masters in Ahn'Qiraj. Any assistance that you can lend will be greatly appreciated. As you can see, I am collecting thorium bars here for the war effort. We need to gather $2012w in total, and currently we have $2011w.","$C|1이여;여;, 잘 들으세요. 지금 얼라이언스와 호드는 실리시드와 그들을 조종하는 무리와 싸울 안퀴라즈 전쟁을 준비하고 있어요. 도와주신다면 정말 감사하겠습니다. 보시다시피 저는 전쟁에 필요한 토륨 주괴를 모으고 있습니다. 모두 $2012w개가 필요한데 현재 보유하고 있는 것은 $2011w개입니다."}
rows[#rows+1]={"$C, the cataclysm has crumbled the mountains and the South Sea has rushed in to drown Thousand Needles.$B$BWe need your help, now!","$C|1이여;여;, 대격변으로 산이 무너지고 남쪽 바다가 범람하여 버섯구름 봉우리가 잠겼습니다.$B$B지금 그대의 도움이 필요합니다!"}
rows[#rows+1]={"$C, through the efforts of many we have managed to gather up all of the runecloth bandages that the Alliance feels it needs for the upcoming conflict. Were I you, I would ask some of the others here to see if they still have collection tasks that need fulfilling.","많은 얼라이언스의 동지들이 도와주신 덕분에 다가오는 안퀴라즈 전쟁에서 연합에 필요한 룬무늬 붕대를 가까스로 모을 수 있었습니다. 내가 그대라면 이곳에서 다른 물자를 모으고 있는 이들 중 도움이 필요한 이는 없는지 알아보겠소이다."}
rows[#rows+1]={"$C, we are not ashamed to say that we are in need of all of the assistance that we can get in our fight at Warsong Gulch.  But there is greater honor to be had now than at any time in the past if you so choose to lend us your skills.  As well, the Silverwing Sentinels are sure to look more favorably upon your efforts on our behalf.  Will you join the battle?","우린 솔직히 말해서 전쟁노래 협곡의 전투를 위해 그 어떤 도움의 손길이라도 마다하지 않습니다. 우릴 돕는다면 그 어느 때보다 큰 명예를 얻을 수 있답니다. 그리고, 그대의 노고는 분명 은빛날개 파수대로부터 좋은 평판을 살 거고요. 전장에 참여하시겠습니까?"}
rows[#rows+1]={"$C, we have a great need for your help in Warsong Gulch against the Silverwing Sentinels.  And there is even greater honor and reputation with the Warsong Outriders to be gained as well!  Do you have the courage to enter battle?","$c|1이여;여;, 은빛날개 파수대와 전쟁이 벌어지는 전쟁노래 협곡에서는 지금 당신의 도움을 절실히 필요로 하고 있습니다. 성공만 하면 큰 명예는 물론 전쟁노래 정찰대에서 당신의 평판도 크게 오를 겁니다! 자, 전장에 참여할 용기가 있습니까?"}
rows[#rows+1]={"$C, we need your assistance at Warsong Gulch.  Will you aid us in our fight against the Warsong Outriders?","$C|1이여;여;, 전쟁노래 협곡에서는 지금 그대에게 도움을 요청하고 있습니다. 우리를 도와 전쟁노래 정찰대에 맞서 주십시오!"}
rows[#rows+1]={"$C, you didn't happen to see a courier on your way here? We are awaiting word from Silvermoon City and their messenger is late!","여기 오면서 급사 한 명을 만나지 못했습니까? 실버문의 소식을 기다리는 중인데 아직 전갈이 도착하지 않았습니다!"}
rows[#rows+1]={"$G Brother:Sister;, you are now considered bound by blood to the Netherwing. All of Netherwing will be behind you now! The time to strike at the heart of our enemies is now, friend! We must reclaim our lost heritage.","$G형제:자매;여, 그대는 황천의 용군단과 피로 결속되어 있다는 걸 잊지 마십시오. 모든 황천의 용군단이 그대를 지지할 것입니다! 적의 심장부를 공격할 때가 바로 지금입니다, 동지여! 우리의 잃어버린 유산을 되찾아야 합니다."}
rows[#rows+1]={"$G King : Queen; not angry with me?","$G왕:여왕;님 나에게 화 안 나셨나?"}
rows[#rows+1]={"$G Mister:Missy;, if I didn't know better, I'd think you were one of them 'special' peoples. We call em Troggs.$B$BWindsor didn't have no beef with the Dark Irons, after all, his great, great, grand pappy's best friend was a Dark Iron. Which is also probably why that army of Dark Irons didn't kill him on sight.","아, 이 답답한 친구야... 당신 사실은 $R|1이;가; 아니라 그 \"특이한\" 종족 아니오? 우리는 트로그라고 부르는 멍청한 놈들 말이지.$B$B윈저 님과 검은무쇠 부족의 사이는 나쁘지 않았소. 고조 할아버지의 죽마고우가 바로 검은무쇠 드워프였으니까. 아마 그래서 검은무쇠 부족에서 윈저 님을 보고도 즉시 사살하지 않았던 것 같소."}
rows[#rows+1]={"$G Mr. : Ms.; $N, so very good to see you.$B$BI hope that you are enjoying the Kaja'Cola marketing campaign. We're planning a massive set of explosions for the next phase of the campaign. That always goes over well with our target demographic.","$n 님, 만나서 반가워요.$B$B카자콜라 광고는 잘 보고 계시겠죠? 다음 단계에는 더 엄청난 걸 터뜨릴 계획이에요. 언제나 그렇듯 목표 시장에 꼭 맞는 광고지요."}
rows[#rows+1]={"$G Mr. : Ms.; $n, so very good to see you.$B$BI hope that you are enjoying the Kaja'Cola marketing campaign. We're planning a massive set of explosions for the next phase of the campaign. That always goes over well with our target demographic.","$n 님, 만나서 반가워요.$B$B카자콜라 광고는 잘 보고 계시겠죠? 다음 단계에는 더 엄청난 걸 터뜨릴 계획이에요. 언제나 그렇듯 목표 시장에 꼭 맞는 광고지요."}
rows[#rows+1]={"$G Sir : Ma'am;! I'm here to assist and defend you.$B$BYour orders?","당신을 지원하고 보호하는 임무를 띠고 왔습니다.$B$B명령을 내려 주십시오."}
rows[#rows+1]={"$G Sir : Ma'am;, yes $g sir : ma'am;! Private Porter reporting for duty and ready to assist you with your medium leather collection needs. The Ahn'Qiraj War is coming and we need to be as prepared as we can be.$B$BAs you can see we have collected exactly $2063w pieces of medium leather, and I have been tasked with gathering a total of $2064w.","네, 그렇습니다! 병사 포터가 보고 드립니다. 일반 가죽 모으는 일을 도와드리겠습니다. 우리는 다가올 안퀴라즈 전쟁에 대비하여 만반의 준비를 해야합니다.$B$B보시다시피 정확하게 $2063w개의 일반 가죽을 모았고 제가 맡은 임무는 모두 $2064w개를 모으는 것입니다."}
rows[#rows+1]={"$G Sir.:Ma'am.;","명령은?"}
rows[#rows+1]={"$G Son : Young lady;, I'm not going to lie to you; things aren't pretty around here.  We're under constant assault by the bugs and our very way of life, our freedom, is at stake!$B$BAre you going to be a responsible citizen and help out?","당신에게 거짓말은 하지 않겠습니다. 이곳 주변의 상황이 그리 좋지는 않습니다. 우리는 벌레들의 끊임없는 공격에 시달리고 있습니다. 우리 삶과 자유까지 위협받고 있단 말입니다!$B$B책임감 있는 $r|1으로서;로서; 우리를 도와주지 않겠어요?"}
rows[#rows+1]={"$N smash warp-gate good, but da demons make it strong again.$B$B$N bring Gahk another darkrune and Gahk make special crystalforged darkrune for $N!","$n 공간이동 관문 잘 부쉈지만 그 악마들 다시 관문 튼튼하게 하고 있다.$B$B$n 가크에게 암흑룬 더 가져오면 가크 $n 위해 귀한 수정으로 벼려낸 암흑룬 만들어 준다!"}
rows[#rows+1]={"$N!  I hardly recognized you in your new outfit.  Still have that tunic... or did you take the chausses... or was it the staff?   I can't recall, it was so long ago...$B$BWell, I'm glad you are here to help out again.  We could use all the help we can get.  $N, if you perform the way you did back in Westfall with the People's Militia, we have a chance.$B$BThese are dire times, if we don't win this battle, there may not be a Westfall to return to.","$n! 모습이 달라져서 못 알아봤네. 아직 그 튜닉을 입고 있군... 아니 그 다리보호구를 입었었던가... 예전에도 그 지팡이를 들었었나? 기억이 안 나는군. 너무 오래전이니 말이야..$B$B어쨌든 우리를 도와주러 여기까지 오다니 기쁘네. 어떤 도움이라도 가리지 않고 환영일세. $n, 귀관이 백성의 민병대와 함께 서부 몰락지대에서처럼만 해준다면 우리에게도 기회가 있네.$B$B상황이 그리 좋지 않네. 이 싸움에서 이기지 못한다면, 돌아갈 서부 몰락지대는"}
rows[#rows+1]={"$N!  I hear you're Ironstock's new little whipping $r.  What's she got ya doin' now?","$n! 당신이 아이언스톡의 새로운 희생양이라더군요. 당신에게는 또 무슨 일을 시키던가요?"}
rows[#rows+1]={"$N!  I hope you're ready to get to work, because there is much for you to do here on Sunstrider Isle.$B$BEver since the destruction of the Sunwell by Arthas and the Scourge, we have been a race adrift on a sea of uncertainty.  We teeter on the edge of oblivion.  This will change, $c, and you will learn and aid our recovery at the same time.$B$BThe Outland awaits us!","$n! 그대의 여정을 시작할 준비가 되어 있기를 바랍니다. 여기 선스트라이더 섬에는 할 일이 아주 많답니다.$B$B아서스와 스컬지에게 태양샘이 파괴된 후로, 우리 종족은 거친 바다를 표류하는 신세가 되었지요. 그리고 이제 세상에서 잊혀지느냐 마느냐의 갈림길에 서 있습니다. 하지만, 이 상황은 바뀔 것입니다. 그대의 도움으로 우리는 지난날로 돌아갈 수 있을 것이며, 그대도 많은 것을 배울 것입니다.$B$B아웃랜드가 우리를 기다리고 있습니다!"}
rows[#rows+1]={"$N!  I remember your hunting prowess all too well.  You might have gotten off to a shaky start in Stranglethorn, but you stuck in there and became one o' the finest when you bagged old Bangalash.$B$BBut listen, $g lad : lass;, the prey out here in the Outland is the real deal.  And I've the scars to prove it!","$n! 당신의 사냥 실력 역시 매우 뛰어난 걸 기억하고 있소이다. 가시덤불 골짜기에서 사냥을 시작한 당신은 처음에는 약간 불안했지만 늙은 뱅갈라시까지 잡고 최고의 사냥꾼이 됐지.$B$B하지만, 내 말을 잘 들으시오. 여기 아웃랜드의 사냥감은 차원이 다른 녀석들이라오. 내 몸에 녀석들이 얼마나 강력한지를 보여주는 상처도 있다오!"}
rows[#rows+1]={"$N!  Our supplies are dwindling and until we get more we can't launch large ground assaults into the Field of Strife!$B$BSpeak with the Stormpike Quartermaster.  He'll tell you what you can do to resupply our assault forces.","$n! 보급품이 점점 줄어들고 있어서 더 모으기 전에는 투쟁의 벌판에서 대규모 지상 공격을 펼칠 수가 없네!$B$B우리 병참장교와 얘기해 보게나. 우리 부대에 보급품을 보충하기 위해 자네가 할 수 있는 일이 뭔지 말해 줄 걸세."}
rows[#rows+1]={"$N!  Thanks again for all the help.","$n! 도와주셔서 감사합니다!"}
rows[#rows+1]={"$N! Come here! Surely you know of the battle that rages within Alterac Valley back on Azeroth. We need every able-bodied fighter we can muster. Fight with the Stormpike Guard and defeat the Frostwolves!","$n! 어서 오게! 아제로스의 알터랙 계곡에서 피 튀기는 싸움이 벌어지고 있다는 소식은 자네도 들어봤겠지. 우리는 뛰어난 용사들을 소집하고 있네. 스톰파이크 경비대와 함께 서리늑대 부족을 물리쳐 주게!"}
rows[#rows+1]={"$N! How can I help you, old friend?","$n! 제가 뭘 도와드리면 좋겠습니까?"}
rows[#rows+1]={"$N! How ya doin', hon?","멋있는 $n 님! 잘 지내나요?"}
rows[#rows+1]={"$N! You wanna help me out here with Fizz? He's up to no good again!","$n! 내가 여기에서 나갈 수 있게 피즈와 함께 도와주겠다고? 그 녀석은 또 나쁜 일을 꾸미는 중이야!"}
rows[#rows+1]={"$N, $N. Can I call you $N?$B$BI am hanging from a meathook in the back of an ogre cave.$B$BHow do you THINK my research is progressing, you pompous dirt-sucking ass-$c? C'mere! C'mere you son of a swineherd!$B$B<Kristoff flutters back and forth on his chain, trying desperately to kick you in the face.>","$n, $n. 그냥 $n|1이라고;라고; 불러도 되겠소?$B$B혹시 지금 내가 오우거 동굴 속에 있는 고리에 매달려 있는 거 안 보이오?$B$B그런데, 뭐? 내 연구가 어떻게 돼 가고 있냐고? 이 거만하고 지저분한 $c 놈 같으니. 이리 와! 이리 오라고! 이 더러운 자식!$B$B<크리스토프가 기를 쓰고 쇠사슬을 흔들며 당신 얼굴을 걷어차려고 애씁니다.>"}
rows[#rows+1]={"$N, I am not surprised to see you here. I always thought you were my brightest pupil. I am honored to fight alongside you, my friend.","$N, 여기서 널 만나도 놀랍진 않구나. 난 늘 네가 가장 총명한 제자라고 생각했어. 친구여, 너와 함께 싸울 수 있어 영광이다."}
rows[#rows+1]={"$N, I'm glad that you're here. Maybe I can teach you a thing or two.$B$BWhat do you think, $g sir : ma'am;?","$n, 와줘서 고맙군. 자네에게 가르쳐줘야 할 기술이 몇 가지 있다네.$B$B어떻게 생각하는가?"}
rows[#rows+1]={"$N, I've come to find out how rampant the effects of Fel Moss are throughout Darkshore. The corruption of Teldrassil and our surrounding lands really concerns the druids of the Cenarian Circle, and all Night elves.$B$BIt is my goal to find out why this has happened and to put an end to it.","나는 어둠해안에 악마의 이끼가 얼마만큼 퍼져 있는지 조사하러 왔소. 텔드랏실과 일대에 남은 타락의 기운이 퍼져 가고 있어서 세나리온 의회 드루이드들과 모든 나이트 엘프들이 심히 걱정하고 있지.$B$B이 사태의 원인을 알아내고 수습하는 게 내 목표라오."}
rows[#rows+1]={"$N, good to see you!$B$BOr is this the first time that we've met?$B$BI'm in so many places and times right now, I sometimes have a hard time keeping track of all of it.","$n, 다시 만나서 반가워요!$B$B아니, 이번이 처음 만나는 거였나요?$B$B워낙 여러 장소와 시간대를 넘나들고 있어 가끔 헷갈릴 때가 있어요."}
rows[#rows+1]={"$N, have ye any idea o' what we're up against in Alterac Valley?  Are ye ready to fight the Frostwolf Clan?","$n, 알터랙 계곡에서 우리가 상대할 적이 도대체 어떤 놈들인지는 아십니까? 바로 서리늑대 부족입니다. 준비는 됐겠지요?"}
rows[#rows+1]={"$N, how may I further your training in the eyes of the Earth Mother?","$N어떻게 지구 어머니 앞에서 당신의 훈련을 계속할 수 있을까요?"}
rows[#rows+1]={"$N, how may I further your training?","$n 님, 어떻게 훈련을 도와드릴까요?"}
rows[#rows+1]={"$N, it is good to see you again.$B$BRemember to stay focused on your learning.  You represent our future, and should you falter our future will be dark indeed.","$n 님, 다시 만나서 반갑습니다.$B$B배움에 집중하십시오. 그대의 어깨에 우리 미래가 달렸습니다. 그대가 흔들린다면 우리의 미래는 암울해질 것입니다."}
rows[#rows+1]={"$N, it is good to see you.  Our war with the other elemental lords yet rages, but your efforts help ensure our victory.","만나서 반갑군. 또 다른 정령 군주들과 대적하는 우리의 전투는 아직 격해지지 않지만 자네의 노력은 우리가 승리하는 데 도움이 될 것이야."}
rows[#rows+1]={"$N, it is good to see you. Have you come to help push the front for us?","$n 님, 만나서 반갑습니다. 우리가 진격하는 것을 도우러 오신 것입니까?"}
rows[#rows+1]={"$N, it's good to see veterans like you in the field!  I'm sorry to report that our supplies are currently too low to launch any large ground assaults against the Horde.$B$BSpeak with our quartermaster; he has supply missions available.","$n, 자네처럼 노련한 이를 전장에서 보게 되다니 반갑네! 유감스럽게도 현재 우리는 보급품이 너무 적어서 호드에 대한 대규모 지상 공격을 펼칠 수 없는 상태라네.$B$B우리 병참장교와 얘기해 보게. 보급품 관련 임무를 줄 걸세."}
rows[#rows+1]={"$N, it's good to see you again!  Are you having fun at the Faire?$B$BWant to arm wrestle?  No, of course not... you want to keep your arm!","$n, 다시 만나 반가워요! 축제에서 즐거운 시간 보내고 계신가요?$B$B팔씨름 한 판 하실래요? 물론, 피하시겠죠... 팔이 부러지고 싶지는 않을 테니까요!"}
rows[#rows+1]={"$N, my $g boy : girl;!$B$BWant me to teach you any of my thermal palms healing techniques?$B$BNo? How about bandages? Do you want to learn about bandages?","$n, 이봐!$B$B'손바닥 열 치료법'을 전수받고 싶은가?$B$B아니라고? 붕대는 어때? 붕대 감는 법은 배우고 싶지 않아?"}
rows[#rows+1]={"$N, please make sure that you tell Gahruj of our success.","$n, 가루즈에게 우리가 성공했다는 소식을 전해 주십시오."}
rows[#rows+1]={"$N, right? Word of advice: don't let the Trade Prince catch you around here. He knows you're after his job.$B$BEveryone knows.","$n|1이라고;라고; 하셨나요? 충고 하나 할게요. 여기 있다가 무역왕에게 들키지 마시라고요. 당신이 그 자리를 노리고 있다는 사실을 아니까요.$B$B다들 알고 있고 말고요."}
rows[#rows+1]={"$N, sit on down. The fire's warm and the monkeys don't seem to like it.","이봐, $n. 앉아봐. 불이 꽤 따뜻한데다 원숭이들은 불을 별로 좋아하지 않는 것 같으니 말이야."}
rows[#rows+1]={"$N, the Silverwing Sentinels must be crushed!  Are you ready for Warsong Gulch?","$n, 은빛날개 파수대를 반드시 물리쳐야 하네! 전쟁노래 협곡에서 싸울 준비는 됐나?"}
rows[#rows+1]={"$N, the Sons of Lothar have fought here, on the Hellfire Peninsula, for two decades.  We are beset on all sides by indigenous orcs and hellish demons of the Burning Crusade, and though our hearts still beat fiercely, years of war have reduced our numbers.$B$BYou, and the influx of Azeroth's new generation of heroes, are a welcome sight indeed!","$n, 로서의 후예들은 여기 지옥불 반도에서 20년 동안을 싸워 왔네. 우리는 이곳의 토착 오크들과 불타는 성전의 끔찍한 악마들에게 사방으로 포위되었네. 우리의 가슴은 여전히 힘차게 고동치고 있지만 수년간의 전쟁을 치르면서 그 수가 많이 줄었지.$B$B자네와 아제로스에서 온 영웅들이 등장한 것은 정말 반가운 일이라네!"}
rows[#rows+1]={"$N, the Stormpike Guard is in need of your aid in the battle against the Frostwolf Clan in Alterac Valley, now more than ever.  The opportunities for honor and repute are greater than ever as well! Will you join the battle?","$N스톰파이크 경비대는 얼스트울프 클랜과의 전투에 당신의 도움이 필요하고, 이제 어느 때보다 더 많은 명예와 명성을 얻을 수 있는 기회도 있습니다."}
rows[#rows+1]={"$N, the Twilight slaves you and others have been rescuing from Wolf's Run are wandering into camp, but they can't tell me who they are and they speak in riddles and gibberish.$B$BI thought Twilight's Hammer kept the slaves in line the old fashioned way - you know, whips and chains - but it's clear that there's some brainwashing at work...\013\010\013\010","$n 님, 늑대의 터에서 당신과 다른 사람들이 풀어 준 황혼의 노예들이 야영지로 모여들고 있지만, 어떻게 된 일인지 자신에 대해 말하지는 못하고 수수께끼 같은 말만 하며 횡설수설하고 있어요.$B$B저는 황혼의 망치단이 옛날 방식으로 노예들을 부린다고 생각했어요. 채찍이나 쇠사슬 같은 것들로 말이죠. 지금 보니 뭔가 다른 방법으로 노예를 세뇌시키는 게 분명해요...\010"}
rows[#rows+1]={"$N, this came for you this morning.","오늘 아침 당신 앞으로 이것이 왔습니다."}
rows[#rows+1]={"$N, was it? That is a mighty fine piece of work ye have there. I'll take ye on, train ye how to make armor fit fer King Magni himself.","$n|1이라;라; 했소? 아주 강하고 훌륭한 걸 걸치고 있군그래. 훈련을 시켜주지. 마그니 왕께서 몸소 걸칠 만큼 훌륭한 갑옷을 만드는 법을 가르쳐주겠소."}
rows[#rows+1]={"$N, we have enough supplies to launch ground assaults into the Field of Strife.  If you want to send the orders, and your rank is high enough, then speak with Sergeant Yazra Bloodsnarl in Frostwolf Village.","$n, 투쟁의 벌판에 대한 지상 공격을 펼치는 데 필요한 보급품이 충분히 모아졌소. 공격명령서를 보내길 원하고 또 당신 계급이 충분히 높다고 생각한다면 서리늑대 마을에 있는 하사관 야즈라 블러드스날에게 가서 얘기를 나눠 보시오."}
rows[#rows+1]={"$N, we have enough supplies to launch ground assaults.  If your standing with the Stormpike Guard is high enough, then speak with Corporal Noreg Stormpike.","$n, 우리에겐 지상 공격을 펼치는 데 필요한 보급품이 충분히 있소. 스톰파이크 경비대에서 지위가 충분히 높다면 하사관 노레그 스톰파이크와 얘기해 보시오."}
rows[#rows+1]={"$N, what are you waiting for?  Find Field Marshal Teravaine in the Field of Strife and give him the assault orders.  Once he gets the orders, he and his troops will charge into the Horde and take no prisoners!","뭘 우물쭈물 하고 있는 거요, $n? 투쟁의 벌판에서 테라베인 야전사령관을 찾아 공격명령서를 전해 주시오. 명령서를 받으면 그와 그 부대가 호드 진영으로 쳐들어가 놈들을 말살시켜 버릴 테니까."}
rows[#rows+1]={"$N, what are you waiting for?  Find Field Marshal in the Field of Strife and give him the assault orders.  Once he gets the orders, he and his troops will charge into the Horde and take no prisoners!","뭘 우물쭈물 하고 있는 거요, $n? 투쟁의 벌판에서 테라베인 야전사령관을 찾아 공격명령서를 전해 주시오. 명령서를 받으면 그와 그 부대가 호드 진영으로 쳐들어가 놈들을 말살시켜 버릴 테니까."}
rows[#rows+1]={"$N, you are ready for the ultimate task.  The fiery runes etched on the floor of the molten core are conduits to the realm of fire, and their presence is both an affront to us and a source of power for the Firelords.  They must be extinguished!$B$BTo extinguish a rune, take a vial of aqual quintessence.  Pour it on the rune and its flame will go out, rendering it useless and weakening our enemy!","$n, 이제 최종 임무를 수행할 준비가 되었군. 화산 심장부 바닥에 새겨진 불의 룬은 불의 세계로 통하는 길로서, 불의 군주들에게 마력을 부여하는 원천이노라. 우리에게는 치욕의 상징일 뿐이지. 반드시 그것을 꺼야만 하노라!$B$B룬을 끄려면 물의 진수를 한 병 들고 가서 그 위에 부어야 한다. 그러면 불길이 꺼져 룬은 제 힘을 잃어버릴 것이고 당연히 우리의 적들도 약해질 것이다!"}
rows[#rows+1]={"$N, you gonna save us from those pirates, or what?!","$n, 날 이 해적들로부터 구할 거야, 말 거야?!"}
rows[#rows+1]={"$N, you gotta get in there and save our people!","$n 님, 저 안으로 가서 고블린을 구해주세요!"}
rows[#rows+1]={"$N, you return!  The spirits of my last meal said you would come see me and that we would discuss business.$B$BWere they correct?","오, 자네 돌아왔군! 지난밤에 찾아온 어떤 영혼이 그러더군. 자네가 곧 나를 찾아와서 일 얘기를 하게 될 거라고 말이야.$B$B그 말이 맞는 건가?"}
rows[#rows+1]={"$N? $G Sir : Ma'am;, you're not a hunter, you're a $c.","$n? 넌 사냥꾼이 아니라 $c|1이잖아;잖아;? 왜 날 귀찮게 하는 거야?"}
rows[#rows+1]={"$N?! What are you still doing here?$B$BYou have to get off of the island, or better yet, into one of my Town-In-A-Boxes!$B$BDon't wait too long, my $g boy : girl;! The Cataclysm is upon us!","$n?! 여기서 뭐 하는 거야?$B$B당장 이 섬에서 떠나야 해! 아니면 내 상자 마을 중 하나로 들어가는 편이 더 낫고!$B$B너무 오래 기다리지 말라고! 대격변이 시작됐어!"}
rows[#rows+1]={"$R! Yes, you! Why do you waste time dawdling in this wreck of a city when your rightful place is in Arathi Basin? The League of Arathor is ruthless in its assault; your contribution is needed, and you will be rewarded!","$R 친구! 그래, 자네! 아라시 분지에 있어야 할 시간에 왜 여기서 빈둥거리며 시간을 낭비하고 있나? 아라소르 연맹이 무자비한 공격을 퍼붓고 있어. 자네의 도움이 필요하네. 물론 보상도 있을 거야!"}
rows[#rows+1]={"$R, report! What news of significance do you bring? Be quick about your business... Dame Auriferous and I are in the middle of a strategic discussion.","보고하라, $R|1이여;여;! 중요한 소식이라도 가져 왔나? 용건만 빨리 말해라. 귀부인 아우리페러스와 전략 회의 중이었다."}
rows[#rows+1]={"$R, why would I want to talk to you? Your people probably caused this mess in the first place!","$R 양반, 내가 왜 당신과 얘기해야 하죠? 이런 사태가 일어난 것도 다 당신들 책임일 텐데!"}
rows[#rows+1]={"$R. Have you been sent to speak with me? How long has it been since the master's demise on these very slopes?","나와 이야기를 나누러 왔나, $R? 주인님이 이 산에서 쓰러지신 지 얼마나 지났지?"}
rows[#rows+1]={"$c! Zaela said the Horde would provide us with weapons. What do you have?","$c- 자엘라가 말했어 호드 무기를 공급해 줄 거야"}
rows[#rows+1]={"$n smash warp-gate good, but da demons make it strong again.$B$B$n bring Gahk another darkrune and Gahk make special crystalforged darkrune for $n!","$n 공간이동 관문 잘 부쉈지만 그 악마들 다시 관문 튼튼하게 하고 있다.$B$B$n 가크에게 암흑룬 더 가져오면 가크 $n 위해 귀한 수정으로 벼려낸 암흑룬 만들어 준다!"}
rows[#rows+1]={"$n!  I hardly recognized you in your new outfit.  Still have that tunic... or did you take the chausses... or was it the staff?   I can't recall, it was so long ago...$B$BWell, I'm glad you are here to help out again.  We could use all the help we can get.  $n, if you perform the way you did back in Westfall with the People's Militia, we have a chance.$B$BThese are dire times, if we don't win this battle, there may not be a Westfall to return to.","$n! 모습이 달라져서 못 알아봤네. 아직 그 튜닉을 입고 있군... 아니 그 다리보호구를 입었었던가... 예전에도 그 지팡이를 들었었나? 기억이 안 나는군. 너무 오래전이니 말이야..$B$B어쨌든 우리를 도와주러 여기까지 오다니 기쁘네. 어떤 도움이라도 가리지 않고 환영일세. $n, 귀관이 백성의 민병대와 함께 서부 몰락지대에서처럼만 해준다면 우리에게도 기회가 있네.$B$B상황이 그리 좋지 않네. 이 싸움에서 이기지 못한다면, 돌아갈 서부 몰락지대는 없을 걸세."}
rows[#rows+1]={"$n!  I hear you're Ironstock's new little whipping $r.  What's she got ya doin' now?","$n! 당신이 아이언스톡의 새로운 희생양이라더군요. 당신에게는 또 무슨 일을 시키던가요?"}
rows[#rows+1]={"$n!  I hope you're ready to get to work, because there is much for you to do here on Sunstrider Isle.$B$BEver since the destruction of the Sunwell by Arthas and the Scourge, we have been a race adrift on a sea of uncertainty.  We teeter on the edge of oblivion.  This will change, $c, and you will learn and aid our recovery at the same time.$B$BThe Outland awaits us!","$n! 그대의 여정을 시작할 준비가 되어 있기를 바랍니다. 여기 선스트라이더 섬에는 할 일이 아주 많답니다.$B$B아서스와 스컬지에게 태양샘이 파괴된 후로, 우리 종족은 거친 바다를 표류하는 신세가 되었지요. 그리고 이제 세상에서 잊혀지느냐 마느냐의 갈림길에 서 있습니다. 하지만, 이 상황은 바뀔 것입니다. 그대의 도움으로 우리는 지난날로 돌아갈 수 있을 것이며, 그대도 많은 것을 배울 것입니다.$B$B아웃랜드가 우리를 기다리고 있습니다!"}
rows[#rows+1]={"$n!  I remember your hunting prowess all too well.  You might have gotten off to a shaky start in Stranglethorn, but you stuck in there and became one o' the finest when you bagged old Bangalash.$B$BBut listen, $g lad : lass;, the prey out here in the Outland is the real deal.  And I've the scars to prove it!","$n! 당신의 사냥 실력 역시 매우 뛰어난 걸 기억하고 있소이다. 가시덤불 골짜기에서 사냥을 시작한 당신은 처음에는 약간 불안했지만 늙은 뱅갈라시까지 잡고 최고의 사냥꾼이 됐지.$B$B하지만, 내 말을 잘 들으시오. 여기 아웃랜드의 사냥감은 차원이 다른 녀석들이라오. 내 몸에 녀석들이 얼마나 강력한지를 보여주는 상처도 있다오!"}
rows[#rows+1]={"$n!  Our supplies are dwindling and until we get more we can't launch large ground assaults into the Field of Strife!$B$BSpeak with the Stormpike Quartermaster.  He'll tell you what you can do to resupply our assault forces.","$n! 보급품이 점점 줄어들고 있어서 더 모으기 전에는 투쟁의 벌판에서 대규모 지상 공격을 펼칠 수가 없네!$B$B우리 병참장교와 얘기해 보게나. 우리 부대에 보급품을 보충하기 위해 자네가 할 수 있는 일이 뭔지 말해 줄 걸세."}
rows[#rows+1]={"$n!  Thanks again for all the help.","$n! 도와주셔서 감사합니다!"}
rows[#rows+1]={"$n! Come here! Surely you know of the battle that rages within Alterac Valley back on Azeroth. We need every able-bodied fighter we can muster. Fight with the Stormpike Guard and defeat the Frostwolves!","$n! 어서 오게! 아제로스의 알터랙 계곡에서 피 튀기는 싸움이 벌어지고 있다는 소식은 자네도 들어봤겠지. 우리는 뛰어난 용사들을 소집하고 있네. 스톰파이크 경비대와 함께 서리늑대 부족을 물리쳐 주게!"}
rows[#rows+1]={"$n! How can I help you, old friend?","$n! 제가 뭘 도와드리면 좋겠습니까?"}
rows[#rows+1]={"$n! How ya doin', hon?","멋있는 $n 님! 잘 지내나요?"}
rows[#rows+1]={"$n! I've been awaiting your return. What be takin' ya so long, mon?$b$bIt be time to complete da conversion of da Blightbloods.$b$bJoin me and witness the creation of our army!","$n! 자네가 돌아오길 기다렸다네. 왜 이렇게 오래 걸렸나, 친구?$b$b역병피 트롤 군대가 완성될 때가 왔네.$b$b이제 나와 함께 가서 우리 군대의 탄생을 지켜보자고!"}
rows[#rows+1]={"$n! I've been wondering how you were. What's kept you?","$n어떻게 지내셨는지 궁금했어요?"}
rows[#rows+1]={"$n! You wanna help me out here with Fizz? He's up to no good again!","$n! 내가 여기에서 나갈 수 있게 피즈와 함께 도와주겠다고? 그 녀석은 또 나쁜 일을 꾸미는 중이야!"}
rows[#rows+1]={"$n! You've returned just to talk to me? That's very thoughtful of you, and you look pretty sweet in that outfit, too!$B$BYou don't know how good it makes me feel to see you. It can get pretty lonely up here, what with most of these yahoos not being able to see me, and all. It's a great thing that you did for all of us, and I'll never forget it!$B$BThanks for dropping in and saying hi, and don't be such a stranger.","$n! 제 말벗을 해주려고 돌아왔다고요? 정말 사려 깊은 친구로군요. 그리고 그 옷을 입고 있으니 당신 정말 멋진데요!$B$B다시 만나 얼마나 반가운지 모를 거예요. 여기 있으면 대부분 날 볼 수 없고 또 이것저것 다른 이유로 정말 외롭거든요, 이해하시죠? 당신이 우리 모두에게 해준 일은 정말 위대한 것이었어요. 절대 잊지 않을게요!$B$B일부러 찾아와 말동무가 되어줘서 고마웠어요. 그럼 자주 들러주세요!"}
rows[#rows+1]={"$n, $n. Can I call you $n?$B$BI am hanging from a meathook in the back of an ogre cave.$B$BHow do you THINK my research is progressing, you pompous dirt-sucking ass-$c? C'mere! C'mere you son of a swineherd!$B$B<Kristoff flutters back and forth on his chain, trying desperately to kick you in the face.>","$n, $n. 그냥 $n|1이라고;라고; 불러도 되겠소?$B$B혹시 지금 내가 오우거 동굴 속에 있는 고리에 매달려 있는 거 안 보이오?$B$B그런데, 뭐? 내 연구가 어떻게 돼 가고 있냐고? 이 거만하고 지저분한 $c 놈 같으니. 이리 와! 이리 오라고! 이 더러운 자식!$B$B<크리스토프가 기를 쓰고 쇠사슬을 흔들며 당신 얼굴을 걷어차려고 애씁니다.>"}
rows[#rows+1]={"$n, I am not surprised to see you here. I always thought you were my brightest pupil. I am honored to fight alongside you, my friend.","$n, 여기서 널 만나다니 놀랍군. 난 언제나 네가 내 가장 영리한 제자라고 생각했었다. 너와 함께 싸우게 되어 영광이다, 친구."}
rows[#rows+1]={"$n, I am pleased to see you. Our dwarven allies require our assistance in Alterac Valley. Will you help them?","$n, 만나서 반갑습니다. 알터랙 계곡에 있는 우리 드워프 동맹들이 도움을 요청했습니다. 도움의 손길을 보내 주시겠습니까?"}
rows[#rows+1]={"$n, I'm glad that you're here. Maybe I can teach you a thing or two.$B$BWhat do you think, $g sir : ma'am;?","$n, 와줘서 고맙군. 자네에게 가르쳐줘야 할 기술이 몇 가지 있다네.$B$B어떻게 생각하는가?"}
rows[#rows+1]={"$n, good to see you!$B$BOr is this the first time that we've met?$B$BI'm in so many places and times right now, I sometimes have a hard time keeping track of all of it.","$n, 다시 만나서 반가워요!$B$B아니, 이번이 처음 만나는 거였나요?$B$B워낙 여러 장소와 시간대를 넘나들고 있어 가끔 헷갈릴 때가 있어요."}
rows[#rows+1]={"$n, have ye any idea o' what we're up against in Alterac Valley?  Are ye ready to fight the Frostwolf Clan?","$n, 알터랙 계곡에서 우리가 상대할 적이 도대체 어떤 놈들인지는 아십니까? 바로 서리늑대 부족입니다. 준비는 됐겠지요?"}
rows[#rows+1]={"$n, how may I further your training?","$n 님, 어떻게 훈련을 도와드릴까요?"}
rows[#rows+1]={"$n, it is good to see you again.$B$BRemember to stay focused on your learning.  You represent our future, and should you falter our future will be dark indeed.","$n 님, 다시 만나서 반갑습니다.$B$B배움에 집중하십시오. 그대의 어깨에 우리 미래가 달렸습니다. 그대가 흔들린다면 우리의 미래는 암울해질 것입니다."}
rows[#rows+1]={"$n, it is good to see you.  Our war with the other elemental lords yet rages, but your efforts help ensure our victory.","만나서 반갑군. 또 다른 정령 군주들과 대적하는 우리의 전투는 아직 격해지지 않지만 자네의 노력은 우리가 승리하는 데 도움이 될 것이야."}
rows[#rows+1]={"$n, it is good to see you. Have you come to help push the front for us?","$n 님, 만나서 반갑습니다. 우리가 진격하는 것을 도우러 오신 것입니까?"}
rows[#rows+1]={"$n, it's good to see veterans like you in the field!  I'm sorry to report that our supplies are currently too low to launch any large ground assaults against the Horde.$B$BSpeak with our quartermaster; he has supply missions available.","$n, 자네처럼 노련한 이를 전장에서 보게 되다니 반갑네! 유감스럽게도 현재 우리는 보급품이 너무 적어서 호드에 대한 대규모 지상 공격을 펼칠 수 없는 상태라네.$B$B우리 병참장교와 얘기해 보게. 보급품 관련 임무를 줄 걸세."}
rows[#rows+1]={"$n, it's good to see you again!  Are you having fun at the Faire?$B$BWant to arm wrestle?  No, of course not... you want to keep your arm!","$n, 다시 만나 반가워요! 축제에서 즐거운 시간 보내고 계신가요?$B$B팔씨름 한 판 하실래요? 물론, 피하시겠죠... 팔이 부러지고 싶지는 않을 테니까요!"}
rows[#rows+1]={"$n, my $g boy : girl;!$B$BWant me to teach you any of my thermal palms healing techniques?$B$BNo? How about bandages? Do you want to learn about bandages?","$n, 이봐!$B$B'손바닥 열 치료법'을 전수받고 싶은가?$B$B아니라고? 붕대는 어때? 붕대 감는 법은 배우고 싶지 않아?"}
rows[#rows+1]={"$n, please make sure that you tell Gahruj of our success.","$n, 가루즈에게 우리가 성공했다는 소식을 전해 주십시오."}
rows[#rows+1]={"$n, right? Word of advice: don't let the Trade Prince catch you around here. He knows you're after his job.$B$BEveryone knows.","$n|1이라고;라고; 하셨나요? 충고 하나 할게요. 여기 있다가 무역왕에게 들키지 마시라고요. 당신이 그 자리를 노리고 있다는 사실을 아니까요.$B$B다들 알고 있고 말고요."}
rows[#rows+1]={"$n, sit on down. The fire's warm and the monkeys don't seem to like it.","이봐, $n. 앉아봐. 불이 꽤 따뜻한데다 원숭이들은 불을 별로 좋아하지 않는 것 같으니 말이야."}
rows[#rows+1]={"$n, the Silverwing Sentinels must be crushed!  Are you ready for Warsong Gulch?","$n, 은빛날개 파수대를 반드시 물리쳐야 하네! 전쟁노래 협곡에서 싸울 준비는 됐나?"}
rows[#rows+1]={"$n, the Sons of Lothar have fought here, on the Hellfire Peninsula, for two decades.  We are beset on all sides by indigenous orcs and hellish demons of the Burning Crusade, and though our hearts still beat fiercely, years of war have reduced our numbers.$B$BYou, and the influx of Azeroth's new generation of heroes, are a welcome sight indeed!","$n, 로서의 후예들은 여기 지옥불 반도에서 20년 동안을 싸워 왔네. 우리는 이곳의 토착 오크들과 불타는 성전의 끔찍한 악마들에게 사방으로 포위되었네. 우리의 가슴은 여전히 힘차게 고동치고 있지만 수년간의 전쟁을 치르면서 그 수가 많이 줄었지.$B$B자네와 아제로스에서 온 영웅들이 등장한 것은 정말 반가운 일이라네!"}
rows[#rows+1]={"$n, the Twilight slaves you and others have been rescuing from Wolf's Run are wandering into camp, but they can't tell me who they are and they speak in riddles and gibberish.$B$BI thought Twilight's Hammer kept the slaves in line the old fashioned way - you know, whips and chains - but it's clear that there's some brainwashing at work...\010","$n 님, 늑대의 터에서 당신과 다른 사람들이 풀어 준 황혼의 노예들이 야영지로 모여들고 있지만, 어떻게 된 일인지 자신에 대해 말하지는 못하고 수수께끼 같은 말만 하며 횡설수설하고 있어요.$B$B저는 황혼의 망치단이 옛날 방식으로 노예들을 부린다고 생각했어요. 채찍이나 쇠사슬 같은 것들로 말이죠. 지금 보니 뭔가 다른 방법으로 노예를 세뇌시키는 게 분명해요...\010"}
rows[#rows+1]={"$n, this came for you this morning.","오늘 아침 당신 앞으로 이것이 왔습니다."}
rows[#rows+1]={"$n, was it? That is a mighty fine piece of work ye have there. I'll take ye on, train ye how to make armor fit fer King Magni himself.","$n|1이라;라; 했소? 아주 강하고 훌륭한 걸 걸치고 있군그래. 훈련을 시켜주지. 마그니 왕께서 몸소 걸칠 만큼 훌륭한 갑옷을 만드는 법을 가르쳐주겠소."}
rows[#rows+1]={"$n, we have enough supplies to launch ground assaults into the Field of Strife.  If you want to send the orders, and your rank is high enough, then speak with Sergeant Yazra Bloodsnarl in Frostwolf Village.","$n, 투쟁의 벌판에 대한 지상 공격을 펼치는 데 필요한 보급품이 충분히 모아졌소. 공격명령서를 보내길 원하고 또 당신 계급이 충분히 높다고 생각한다면 서리늑대 마을에 있는 하사관 야즈라 블러드스날에게 가서 얘기를 나눠 보시오."}
rows[#rows+1]={"$n, we have enough supplies to launch ground assaults.  If your standing with the Stormpike Guard is high enough, then speak with Corporal Noreg Stormpike.","$n, 우리에겐 지상 공격을 펼치는 데 필요한 보급품이 충분히 있소. 스톰파이크 경비대에서 지위가 충분히 높다면 하사관 노레그 스톰파이크와 얘기해 보시오."}
rows[#rows+1]={"$n, what are you waiting for?  Find Field Marshal Teravaine in the Field of Strife and give him the assault orders.  Once he gets the orders, he and his troops will charge into the Horde and take no prisoners!","뭘 우물쭈물 하고 있는 거요, $n? 투쟁의 벌판에서 테라베인 야전사령관을 찾아 공격명령서를 전해 주시오. 명령서를 받으면 그와 그 부대가 호드 진영으로 쳐들어가 놈들을 말살시켜 버릴 테니까."}
rows[#rows+1]={"$n, what are you waiting for?  Find Field Marshal in the Field of Strife and give him the assault orders.  Once he gets the orders, he and his troops will charge into the Horde and take no prisoners!","뭘 우물쭈물 하고 있는 거요, $n? 투쟁의 벌판에서 테라베인 야전사령관을 찾아 공격명령서를 전해 주시오. 명령서를 받으면 그와 그 부대가 호드 진영으로 쳐들어가 놈들을 말살시켜 버릴 테니까."}
rows[#rows+1]={"$n, you are ready for the ultimate task.  The fiery runes etched on the floor of the molten core are conduits to the realm of fire, and their presence is both an affront to us and a source of power for the Firelords.  They must be extinguished!$B$BTo extinguish a rune, take a vial of aqual quintessence.  Pour it on the rune and its flame will go out, rendering it useless and weakening our enemy!","$n, 이제 최종 임무를 수행할 준비가 되었군. 화산 심장부 바닥에 새겨진 불의 룬은 불의 세계로 통하는 길로서, 불의 군주들에게 마력을 부여하는 원천이노라. 우리에게는 치욕의 상징일 뿐이지. 반드시 그것을 꺼야만 하노라!$B$B룬을 끄려면 물의 진수를 한 병 들고 가서 그 위에 부어야 한다. 그러면 불길이 꺼져 룬은 제 힘을 잃어버릴 것이고 당연히 우리의 적들도 약해질 것이다!"}
rows[#rows+1]={"$n, you gonna save us from those pirates, or what?!","$n, 날 이 해적들로부터 구할 거야, 말 거야?!"}
rows[#rows+1]={"$n, you gotta get in there and save our people!","$n 님, 저 안으로 가서 고블린을 구해주세요!"}
rows[#rows+1]={"$n, you return!  The spirits of my last meal said you would come see me and that we would discuss business.$B$BWere they correct?","오, 자네 돌아왔군! 지난밤에 찾아온 어떤 영혼이 그러더군. 자네가 곧 나를 찾아와서 일 얘기를 하게 될 거라고 말이야.$B$B그 말이 맞는 건가?"}
rows[#rows+1]={"$n?! What are you still doing here?$B$BYou have to get off of the island, or better yet, into one of my Town-In-A-Boxes!$B$BDon't wait too long, my $g boy : girl;! The Cataclysm is upon us!","$n?! 여기서 뭐 하는 거야?$B$B당장 이 섬에서 떠나야 해! 아니면 내 상자 마을 중 하나로 들어가는 편이 더 낫고!$B$B너무 오래 기다리지 말라고! 대격변이 시작됐어!"}
rows[#rows+1]={"'Ello, $c!$b$bYa ready ta head on down to Venture Bay and crack some Horde skulls?","안녕하신가!$b$b투자개발 만으로 가서 호드 놈들 머리통을 부숴 놓을 준비는 됐나?"}
rows[#rows+1]={"'Twas a fierce battle, $N! Take a moment to rest and gather yer forces. Who knows what lies beyond that door?$B$BLet me know when yer ready and we'll begin our ascent into the upper reaches of the citadel.","격렬한 싸움이었다, $n! 잠시 숨을 돌리면서 힘을 비축하라. 저 문 뒤에 무엇이 도사리는지 누가 알겠나?$B$B준비가 되면 알려라. 성채의 상층 구역으로 올라가기 시작하겠다."}
rows[#rows+1]={"'Twas a fierce battle, $n! Take a moment to rest and gather yer forces. Who knows what lies beyond that door?$B$BLet me know when yer ready and we'll begin our ascent into the upper reaches of the citadel.","격렬한 싸움이었다, $n! 잠시 숨을 돌리면서 힘을 비축하라. 저 문 뒤에 무엇이 도사리는지 누가 알겠나?$B$B준비가 되면 알려라. 성채의 상층 구역으로 올라가기 시작하겠다."}
rows[#rows+1]={"<Anduin sizes you up.>$B$B$N, is it? A few of your triumphs have been the talk of the court.$B$BWhat was it like to serve in Northrend? Have you seen the World Tree? Are the stories about Vashj'ir true? I have so many questions!","<당신을 평가해 보는 안두인>$B$B$n 인가요? 당신이 이룬 업적의 일부 내용을 왕실에서 얘기한 적이 있지요.$B$B노스렌드에서 임무는 어땠나요? 세계수를 봤나요? 바쉬르 얘기가 진짜던가요? 물어보고 싶은 게 많아요!"}
rows[#rows+1]={"<Anduin sizes you up.>$B$B$n, is it? A few of your triumphs have been the talk of the court.$B$BWhat was it like to serve in Northrend? Have you seen the World Tree? Are the stories about Vashj'ir true? I have so many questions!","<당신을 평가해 보는 안두인>$B$B$n 인가요? 당신이 이룬 업적의 일부 내용을 왕실에서 얘기한 적이 있지요.$B$B노스렌드에서 임무는 어땠나요? 세계수를 봤나요? 바쉬르 얘기가 진짜던가요? 물어보고 싶은 게 많아요!"}
rows[#rows+1]={"<Blackhorn strains against his bonds, for the first time visibly upset.>$B$BRedemption! You act as if there's an escape from the Burning Legion. So smug! As though your efforts a decade ago or in Outland have slowed the Legion a single iota! They will come, $r. They will return. And I will be here to welcome them.","<블랙혼이 결박에서 벗어나려 힘을 씁니다. 처음으로 뚜렷한 분노를 드러냅니다.>$B$B구원이라! 마치 불타는 군단으로부터 도망칠 수 있을 것처럼 말하는구나. 아주 건방져! 마치 10년 전의 노력으로, 그리고 아웃랜드에서의 승리로 군단의 침공을 눈곱만큼이라도 늦춘 것처럼 말하는데! 군단은 돌아온다, $r. 돌아오고말고. 그리고 나는 이곳에서 그들을 반갑게 맞이할 것이다."}
rows[#rows+1]={"<Budd rolls his eyes as he sees you draw near>$b$bAhh, yes, the soon-to-be-famous $n!$b$bTo what do I owe the pleasure of your company?","<당신이 다가오는 걸 보자 눈을 굴리는 버드>$b$b아, 당신이로군요. 곧 유명해질 $n 님!$b$b무슨 기쁜 일이 있기에 당신이 절 찾아 주셨을까요?"}
rows[#rows+1]={"<Corastrasza steps between you and the nearby corpse, her face wrinkled with concern.>$B$BI'm sorry, $N. This is a private matter for the red flight to resolve.$B$BPlease see if you can help the others outside.","<걱정스러운 듯 얼굴을 찌푸리며 당신과 시체 사이를 가로막는 코라스트라자>$B$B미안해요, $n. 이건 우리 붉은용군단이 직접 처리해야 할 내부적인 문제입니다.$B$B부디 바깥의 다른 이들을 도와주세요."}
rows[#rows+1]={"<Corastrasza steps between you and the nearby corpse, her face wrinkled with concern.>$B$BI'm sorry, $n. This is a private matter for the red flight to resolve.$B$BPlease see if you can help the others outside.","<걱정스러운 듯 얼굴을 찌푸리며 당신과 시체 사이를 가로막는 코라스트라자>$B$B미안해요, $n. 이건 우리 붉은용군단이 직접 처리해야 할 내부적인 문제입니다.$B$B부디 바깥의 다른 이들을 도와주세요."}
rows[#rows+1]={"<Cyrus's eyes glow brightly>$B$BDo I devour you whole or do I allow you to live?$B$BPerhaps you could still be of some use...$B$BChallenge my minion, $r. Survive and return proof of your victory to me.","<눈이 번쩍이며 빛나는 키루스>$B$B너를 통째로 집어삼킬까? 아니면 좀 더 살려 둘까?$B$B아직 쓸모가 있을지도 모르겠군...$B$B내 부하와 맞서 싸워. 살아남아서 네가 승리한 증거를 가져와."}
rows[#rows+1]={"<Dalin Soft lies beneath the canopy, his breath rattling in a chest that has no more need of it.>$B$BThe Scourge took me once, and the Dark Lady's banshees dragged me back. Now I feel it pulling at me again, $c. Tell me... what waits on the other side?","<Dalin Soft는 캔포프 밑에 누워있으며, 숨은 더 이상 필요하지 않은 가슴에 흔들리고 있습니다.>$B$B이 스컬지 한 번 날 데려갔고, 암흑의 여자의  ⁇ 이 날 끌어들이고 $c말해봐요, 다른 쪽에서 뭘 기다리고 있어요?"}
rows[#rows+1]={"<Goretooth spits.>$B$BI am a warrior of the Horde, $N. It fills me with rage to know that our enemies sit in a fortress, less than a day's ride from Kargath, plotting against us.$B$BHow I long to break free from the bonds of duty and destroy them all in the name of the Warchief.$B$BAlas, we all have roles we must fulfill.$B","<침을 뱉는 고어투스>$B$B나는 호드의 전사라네, $n. 적들이 카르가스에서 하루도 안 되는 거리에 요새를 세워놓고 우리를 공격할 계략을 꾸미고 있다니 화가 치밀어 오르는군.$B$B명령의 구속에서 벗어나 대족장님의 이름으로 녀석들을 말살시켜버리고 싶은 심정이야.$B$B하지만 우리에겐 모두 각자의 역할이 있으니 어쩌겠나."}
rows[#rows+1]={"<Goretooth spits.>$B$BI am a warrior of the Horde, $n. It fills me with rage to know that our enemies sit in a fortress, less than a day's ride from Kargath, plotting against us.$B$BHow I long to break free from the bonds of duty and destroy them all in the name of the Warchief.$B$BAlas, we all have roles we must fulfill.\010","<침을 뱉는 고어투스>$B$B나는 호드의 전사라네, $n. 적들이 카르가스에서 하루도 안 되는 거리에 요새를 세워놓고 우리를 공격할 계략을 꾸미고 있다니 화가 치밀어 오르는군.$B$B명령의 구속에서 벗어나 대족장님의 이름으로 녀석들을 말살시켜버리고 싶은 심정이야.$B$B하지만 우리에겐 모두 각자의 역할이 있으니 어쩌겠나."}
rows[#rows+1]={"<Greatmother Geyah nods, accepting your answer.>$B$BI can no longer fight the spirits, $n. My time has long since passed. Once again, I must thank you for all that you have done. While Garrosh may be unmovable, many of my people have been lifted by your accomplishments. They are now willing to fight for our rights as a united clan.","<당신의 대답에 고개를 끄덕이는 대모 게야>$B$B나는 더 이상 싸울 힘이 없네. 나의 시대는 오래전에 끝났어. 다시 한번 자네에게 고맙다는 말을 하고 싶네. 가로쉬에게는 별 감흥을 주지 못한 것 같네만 자네의 업적은 우리 백성의 용기를 북돋아 주었네. 이제 우리 일족은 단결하여 우리의 권리를 위해 싸울 각오가 되었네."}
rows[#rows+1]={"<Greatmother Geyah smiles at you.>$B$BYou remind me of my son, $n.$B$BHe was an immovable mountain: A pillar of strength and honor.$B$B<Geyah's eyes well up with tears.>$B$BHe sacrificed himself so that we could survive. So that generations of orcs after him could be born into a world without the blood curse... Without Gul'dan and his dark Horde...$B$B<Geyah stares into the distance, lost in thought.>$B$BOh Durotan, how I wish you could be here. Your people so desperately need you...","<당신을 향해 미소를 짓는 대모 게야>$B$B자네를 보니 내 아들이 생각나는군, $n!$B$B아들은 어떤 고난에도 꿈쩍하지 않는 태산과도 같았지. 우리 일족의 힘과 명예의 상징이었다네.$B$B<눈물을 글썽거리는 게야>$B$B그 아이는 우리를 구하기 위해서 자신을 희생했네. 후손들이 피의 저주가 없는 세상에서 살아가게 해주려고... 사악한 굴단과 그의 검은 호드만 아니었다면...$B$B<깊은 생각에 빠져 먼 곳을 바라보는 게야>$B$B듀로탄, 네가 살아 있다면 얼마나 좋을까. 우리 백성에게는 네가 정말 절실하게 필요하구나..."}
rows[#rows+1]={"<Grunt>$b$bYou need something, $r?","<그런트>$b$b뭔가 필요해 $r?"}
rows[#rows+1]={"<High Inquisitor Fairbanks shakes his head.>$B$BNo, $r; only one of his sons is dead. The other lives...$B$B<High Inquisitor Fairbanks points to the sky.>$B$BThe Outland... Find him there... ","<고위검사 페어뱅크스는 머리를 흔들고>$B$B아니, $r; 그의 아들 중 한 명은 죽었고, 나머지 사람은 살아있었다...$B$B<고등검찰 페어뱅크스는 하늘을 가리키고 있습니다>$B$B아웃랜드... 그쪽에서 찾아... "}
rows[#rows+1]={"<Snort> Is this how cowards fight, $r?","<킁킁거리며> 겁쟁이는 이렇게 싸우나, $r?"}
rows[#rows+1]={"<Tarsis groans.>$B$BThere may still be time... Listen closely, mortal.$B$BThrough time and across the Nether I have searched. Deals made with a host of evil and villainy so wretched...$B$B<Tarsis coughs blood into his hands.>$B$BWould you... would you believe that even Elune has turned her back on me, $r? To die here, in this manner now...","<조용히 신음하는 타르시스>$B$B아직 얘기를 나눌 시간은 있을 거야... 잘 들으시오, 필멸의 존재여.$B$B나는 오랫동안 황천을 조사해 왔소. 악마의 군주와 계약을 맺고 사악한 짓을 서슴없이 저질렀지...$B$B<기침을 하며 손에 피를 토하는 타르시스>$B$B엘룬... 심지어 엘룬께서조차 날 버렸다고 한다면 어느 정도인지 짐작이 되나, $r? 여기서 지금 이대로 죽고 싶..."}
rows[#rows+1]={"<Thariel closes his eyes and shakes his head gently. When he opens them again, his gaze is wet and heavy with sorrow.>$b$bI held on to hope… the foolish hope of a dreamer. I should have pressed harder, back when I still had the chance. Begged her not to go. Told her to burn that invitation.$b$bYou are a bearer of grim tidings, $C. Yet still, I owe you. I will not forget this debt.","<타리엘은 눈을 감고 머리를 부드럽게 흔들고 다시 열면 눈은 젖고 슬픔으로 가득합니다.>$b$b꿈꾸는 꿈꾼의 어리석고 희망에 걸려있었지. 내가 기회가 있을 때 더 열심히 노력해야 했지.$b$b실로 그대는 불행한 소식을 전하는 자라 $C하지만 여전히, 난 당신에게 빚을 지고 있습니다."}
rows[#rows+1]={"<The Baron lifts his manacles.>$B$BCome on then, $c. Do ye trust me?","<박은 손목을 들어 올립니다.>$B$B그럼, $c 당신은 나를 신뢰합니까?"}
rows[#rows+1]={"<The apprentice occasionally looks over his shoulder, apparently responding to sounds that you can't hear.>$B$BGood day, $N. Pardon me if I seem distracted, but I'm in the middle of a job for Farmer Natin. I want to have all of his horses shoed by the time he returns from the town hall. What can I help you with?","<아무 소리로 들리지 않는데 가끔 깜짝 놀라서 뒤돌아보는 수습생 안드레단>$B$B안녕하십니까, $n! 실례합니다만 저는 지금 농부 네이든의 일을 하고 있는 중입니다. 그가 마을회관에서 돌아오기 전에 여기 있는 모든 말들에게 발굽을 달아야 해서요. 제가 도울 일이라도 있습니까?"}
rows[#rows+1]={"<The apprentice occasionally looks over his shoulder, apparently responding to sounds that you can't hear.>$B$BGood day, $n. Pardon me if I seem distracted, but I'm in the middle of a job for Farmer Natin. I want to have all of his horses shoed by the time he returns from the town hall. What can I help you with?","<아무 소리로 들리지 않는데 가끔 깜짝 놀라서 뒤돌아보는 수습생 안드레단>$B$B안녕하십니까, $n! 실례합니다만 저는 지금 농부 네이든의 일을 하고 있는 중입니다. 그가 마을회관에서 돌아오기 전에 여기 있는 모든 말들에게 발굽을 달아야 해서요. 제가 도울 일이라도 있습니까?"}
rows[#rows+1]={"<The blood elf quickly regains consciousness as you pour the draught into his mouth.>$B$BI owe you my life, $c.  Without your help I would've succumbed to the Scourge's painful torture.","<입속에 비약을 넣어 주자 빠른 속도로 의식을 회복하는 블러드 엘프>$B$B제 목숨을 구해주셨군요. 그대가 도와주지 않았다면 저는 스컬지의 잔인한 고문에 굴복하고 말았을 것입니다."}
rows[#rows+1]={"<The commander stops his lesson and turns, his eyes appraising you, sizing you up.>$B$BI have use for one such as yourself, $c.","<설명을 중단하고 돌아서서 평가하듯 당신을 바라보는 사령관>$B$B당신같은 $c에게 딱 맞는 일이 있소."}
rows[#rows+1]={"<The emissary sneers without looking at you.>$b$bGo about your business, $r.","<당신을 쳐다보지도 않고 코웃음 치는 사절>$b$b가서 자네 할 일이나 하게, $r."}
rows[#rows+1]={"<The enforcer's eyes flash red.>$B$BI hope your pathetic Horde tries to attack us. I am itching to shed some blood, $c!","<붉게 눈을 번득이는 집행자>$B$B같잖은 너희 호드가 우릴 공격해 줬으면 좋겠군. 피를 보고 싶어서 몸이 근질근질한데 말이야, $c!"}
rows[#rows+1]={"<The old elf leans on the railing, his gaze resting on the canopy far below.>$B$BAh, a young one. When I was your age I carried a glaive against the Legion itself, and I have buried more friends than I can count. Now my days are quiet, and I spend them up here, watching the leaves.$B$BWhat brings you to an old soldier, $c?","<노인 엘프는 릴링에 기대고 그의 시선은 아래쪽의 릴리 위에 있다.>$B$B어, 어릴 적, 네 나이였을 때 레지온 자체에 대한 칼을 들고, 더 많은 친구를 묻고, 이제 내 날이 조용하고, 나는 여기 잎을 지켜보고 있다.$B$B무엇이 당신을 늙은 군인으로 데려가게 했습니까? $c?"}
rows[#rows+1]={"<The old orc is silent for a long moment.>$B$BNow the young ones hurry past this tower with their eyes on Orgrimmar and the glory beyond it. Let them hurry. But someone should remember why there is a Razor Hill at all.$B$BYou have been patient with an old orc's memories, $N. Go on, then. The world will not wait for either of us.","<노인 오크는 잠시 동안 침묵합니다.>$B$B이제 어린아이들은 이 탑을 지나가며 오그리마와 그 너머의 영광을 보고 서둘러 가도록 하자. 하지만 누군가가 왜 래저 힐이 있는지 기억해야 합니다.$B$B당신은 오래된 오크의 기억에 인내심을 가지고 있습니다. $N그럼, 가자. 세상은 우리 둘을 기다리지 않을 거야."}
rows[#rows+1]={"<The trade prince lowers his voice to barely a whisper.>$B$BDon't think for a moment that I've forgotten how much I despise you, $N, rescue or not.$B$BDon't worry your $g simple : pretty; head. I'll get my revenge soon enough, mark my words!$B$BYou'll fare far worse than being my slave. There'll be no escape for you this time.","<목소리를 낮춰 거의 안 들릴 지경으로 속삭이는 무역왕>$B$B한순간도 내가 너를 얼마나 싫어했는지 잊어버렸다고는 생각하지 마, $n. 나를 구해줬건 아니건 말이야.$B$B네 그 $g단순한:예쁘장하기만 한; 머리는 걱정하지 마. 곧 복수할 테니까. 이 말 명심해 두라고!$B$B내가 부리는 노예보다 훨씬 나쁜 대가를 치르게 해 주지. 이번에는 도망갈 수 없을 거야."}
rows[#rows+1]={"<The trade prince lowers his voice to barely a whisper.>$B$BDon't think for a moment that I've forgotten how much I despise you, $n, rescue or not.$B$BDon't worry your $g simple : pretty; head. I'll get my revenge soon enough, mark my words!$B$BYou'll fare far worse than being my slave. There'll be no escape for you this time.","<목소리를 낮춰 거의 안 들릴 지경으로 속삭이는 무역왕>$B$B한순간도 내가 너를 얼마나 싫어했는지 잊어버렸다고는 생각하지 마, $n. 나를 구해줬건 아니건 말이야.$B$B네 그 $g단순한:예쁘장하기만 한; 머리는 걱정하지 마. 곧 복수할 테니까. 이 말 명심해 두라고!$B$B내가 부리는 노예보다 훨씬 나쁜 대가를 치르게 해 주지. 이번에는 도망갈 수 없을 거야."}
rows[#rows+1]={"<Thrall laughs.>$B$BNoted... Now pay attention, $N. The Black Dragonflight brood mother, Onyxia, has been flushed out from her position of power in Stormwind. She has escaped, fleeing to her lair in Dustwallow Marsh.$B$BShe cannot be allowed to live in such close proximity to our capital cities. We must strike before being struck!$B$BI want her destroyed, $N.","<소리 내어 웃는 스랄>$B$B잘 기억해 두지. 자, $n. 내 말을 잘 듣게. 검은용군단의 여왕인 오닉시아가 스톰윈드의 권력층에서 밀려났네. 그 용은 탈출해서 먼지진흙 습지대에 있는 자기 둥지로 도망갔지.$B$B우리 호드의 수도와 그렇게 가까운 곳에서 살게 놔둘 수는 없어! 당하기 전에 우리가 먼저 쳐야 해!$B$B$n, 오닉시아를 처치하게."}
rows[#rows+1]={"<Thrall laughs.>$B$BNoted... Now pay attention, $n. The Black Dragonflight brood mother, Onyxia, has been flushed out from her position of power in Stormwind. She has escaped, fleeing to her lair in Dustwallow Marsh.$B$BShe cannot be allowed to live in such close proximity to our capital cities. We must strike before being struck!$B$BI want her destroyed, $n. ","<소리 내어 웃는 스랄>$B$B잘 기억해 두지. 자, $n. 내 말을 잘 듣게. 검은용군단의 여왕인 오닉시아가 스톰윈드의 권력층에서 밀려났네. 그 용은 탈출해서 먼지진흙 습지대에 있는 자기 둥지로 도망갔지.$B$B우리 호드의 수도와 그렇게 가까운 곳에서 살게 놔둘 수는 없어! 당하기 전에 우리가 먼저 쳐야 해!$B$B$n, 오닉시아를 처치하게."}
rows[#rows+1]={"<Thrall laughs.>$B$BSo much to learn still, $r.$B$BYou are too young to remember the wars and bloodshed of ages past. Too young to remember the burden of the curse carried by our people.$B$BOur position with the Alliance right now is a tenuous one. Skirmishes and smaller battles do take place, but there is peace - something our people have not known for millennia. Would you give this up and plunge us into the maw of chaos again but against a new foe? One that will not rest until we are all destroyed?","'Thrall 웃음.$B$B아직 배울 일이 많지만 $r.$B$B당신은 과거 전쟁과 피 흘리는 것을 기억하기에는 너무 젊고 우리 민족이 가지고 있는 저주의 짐을 기억하기에는 너무 젊어$B$B지금 우리 의 위치 는 얼라이언스 과 희박 한 위치 이다. 교전 과 작은 전투 는 벌어지고 있지만 평화 는 있다. 우리 민족 은 수천 년 동안 알지 못 해 왔던 것 이다. 당신은 이 일을 포기 하고 우리를 다시 혼란의  ⁇  에 빠뜨리겠지만 새로운 적 에게 대항 할 것 이다. 우리 는 모두 멸망 될 때까지 쉬지 않을 것 이다?"}
rows[#rows+1]={"<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$B$G Papa : Mama;...?","<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B$G아빠:엄마;...?"}
rows[#rows+1]={"<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$BThey call you $N. Is this your unique signifier, or is it an honorary title?","<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B사람들이 당신을 $n|1이라고;라고; 부르더군요. 그건 당신만의 고유한 식별자인가요, 아니면 명예 호칭인가요?"}
rows[#rows+1]={"<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$BThey call you $n. Is this your unique signifier, or is it an honorary title?","<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B사람들이 당신을 $n|1이라고;라고; 부르더군요. 그건 당신만의 고유한 식별자인가요, 아니면 명예 호칭인가요?"}
rows[#rows+1]={"<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$BWhat does \"$c\" mean? Are you the goblin $g patriarch : matriarch;?","<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B$c|1이;가; 무슨 뜻이지요? 당신은 고블린 $g아빠:엄마;인가요?"}
rows[#rows+1]={"<Volcor doesn't look at you at all as you get close to him. He seems to be concentrating on keeping his bandages from falling off. After a moment, he looks up at you, a little startled.>$B$BOh, sorry, $c. Now's not a good time. I hope you understand.","<볼코르에게 다가가도 볼코르는 전혀 이쪽을 보지 않습니다. 붕대가 풀리지 않도록 하는 데 집중하고 있는 것 같습니다. 잠시 후 약간 놀란 듯이 이쪽을 봅니다.>$B$B아, 미안하오. 지금은 때가 좋지 않으니 양해를 바라오."}
rows[#rows+1]={"<hic>$b$bIt be lonely in here without me mateys, $g lad:lass;.","딸꾹!$b$b친구도 없이 여기 혼자 있으려니 너무 외롭군."}
rows[#rows+1]={"<hic>Lissen here, $r. Spend a day or two wrestlin' with wild trolls and then tell me how you smell!","<딸꾹> 내 말 들어봐, $r. 거친 트롤들하고 하루나 이틀 정도 씨름하고 나서 무슨 냄새가 나는지 얘기해 보자고!"}
rows[#rows+1]={"<sigh>... Do you think we could move out, $c?$b$bI'm losing fluid fast!","같이 나갈 수 있을 것 같아요? <한숨>$b$b난 출혈이 심각하단 말이에요!"}
rows[#rows+1]={"<sniff's himself, and winces>$b$bThat there be the smell of adventure, $c!","<직접 냄새를 맡아보다가 움찔하는 맥>$B$B무언가 기묘한 일이 일어날 듯한 냄새군, $c 친구!"}
rows[#rows+1]={"A Horde Commendation Signet is awarded to a $g hero : heroine; who goes above and beyond the call of duty to the Horde.  Various Commendation Officers for the factions of the Horde are located in all of the major cities; speak with the one with whom you'd like to raise your reputation, and give them the number of signets they ask for!$B$BBy the way, during the war effort here, if you'd rather receive a material reward for your signets instead of reputation, seek out Warlord Gorchuk.","호드 무공 훈장은 영웅에게 수여되는 것입니다. 호드의 부름을 훌륭히 수행하고 큰 공을 세운 영웅 말입니다. 모든 주요 도시에는 호드의 종족별로 여러 명의 인사 장교가 있습니다. 평판을 높이고 싶은 인사 장교와 얘기해 보고 그들이 요구하는 개수의 무공 훈장을 가져다주십시오!$B$B그나저나 여기서 다가올 전쟁 준비를 하는 동안 평판 대신 훈장으로 보상을 받고 싶다면 장군 고르척을 만나보세요."}
rows[#rows+1]={"A Town-In-A-Box. Nice!$B$BNeed any training, $N?","상자 마을이라니. 멋져!$B$B$n, 훈련을 받고 싶지는 않아?"}
rows[#rows+1]={"A Town-In-A-Box. Nice!$B$BNeed any training, $n?","상자 마을이라니. 멋져!$B$B$n, 훈련을 받고 싶지는 않아?"}
rows[#rows+1]={"A beautiful city, is it not? As was Gilneas, in its time.$B$BBut such things pass, as shall we.  Only the earth and her secrets will remain.$B$BAre you willing to learn, $N?","참 아름다운 도시지 않나요? 전성기 때 길니아스도 그랬죠.$B$B우리도 그렇듯 그런 때는 지났어요. 대지와 대지의 비밀만 남았을 뿐이에요.$B$B$n 님, 드루이드의 길을 배우고자 하시나요?"}
rows[#rows+1]={"A beautiful city, is it not? As was Gilneas, in its time.$B$BBut such things pass, as shall we.  Only the earth and her secrets will remain.$B$BAre you willing to learn, $n?","참 아름다운 도시지 않나요? 전성기 때 길니아스도 그랬죠.$B$B우리도 그렇듯 그런 때는 지났어요. 대지와 대지의 비밀만 남았을 뿐이에요.$B$B$n 님, 드루이드의 길을 배우고자 하시나요?"}
rows[#rows+1]={"A clear voice rises from within the stone...$B$BYou come to us with title and so we will listen, but do not try our patience, $c.  The council has no time for idle gossip from one such as you.","바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신분을 증명했으니 네 얘기를 들어주도록 하지. 하지만 시간은 끌지 않도록 해라. 우리 의회는 너 같은 애송이의 쓸데없는 잡담 따윈 들어줄 시간이 없으니..."}
rows[#rows+1]={"A darkness had fallen over my eyes, but you tore me from my unholy reverie.  You saved me, $N.$B$BAnd now I beg you... to forgive me.","한때 사악한 악의 힘에 의해 판단력이 흐려졌지만, 이제 당신이 저를 사악한 망상으로부터 자유롭게 해주었어요. 절 구하셨군요.$B$B그리고, 부디... 제 잘못을 용서해주세요."}
rows[#rows+1]={"A darkness had fallen over my eyes, but you tore me from my unholy reverie.  You saved me, $n.$B$BAnd now I beg you... to forgive me.","한때 사악한 악의 힘에 의해 판단력이 흐려졌지만, 이제 당신이 저를 사악한 망상으로부터 자유롭게 해주었어요. 절 구하셨군요.$B$B그리고, 부디... 제 잘못을 용서해주세요."}
rows[#rows+1]={"A foul wind blows from the East, $c.","동쪽에서 역풍이 불어오고 있소, $c."}
rows[#rows+1]={"A friend of the Zandalrian! You have ventured deep into the lair of the Blood God, $c. You will do well to listen to what I have to say.$B$BMany thousands of years ago, while the indigenous trolls of the Zul'Aman empire were battling the invading high elf heathens, great magic was stolen from Zanza. This magic was used by the high elves to enchant their weapons and armor to assist in conquering the trolls of the region.","오, 잔달라 부족의 친구로군! 당신은 혈신의 소굴 깊은 곳으로 들어왔소. 그러니 내가 하는 말을 잘 들어야 할 거요.$B$B지금으로부터 수천 년 전, 줄아만 제국의 토착 트롤들이 하이 엘프 침략자들과 싸울 때 이 잔자의 위대한 주술이 도둑을 맞았소. 하이 엘프들은 훔친 주술로 무기와 방어구에 마법을 걸어 이 지역의 트롤들을 완전히 정복하려 했소."}
rows[#rows+1]={"A great evil stirs, $r. Can you feel it?$B$BBah! Of course you cannot. Hand me your armor and weapons and I shall renew their vigor.","거대한 악의 기운이 꿈틀대고 있는데 느껴지십니까?$B$B당연히 못 느끼실 겁니다! 자, 갑옷과 무기를 주십시오. 말끔하게 고쳐드리겠습니다."}
rows[#rows+1]={"A list... how intriguing.  Ah yes, the shipment of fireworks for Lord Saltheril.  He hasn't paid for them; are you here to purchase them on his behalf, $c?","목록을 가져오셨나요? 재미있군요. 아, 그래요. 살데릴 경 앞으로 온 폭죽이 있지만 아직 대금을 받지 못했습니다. 그분 대신 구입하러 오셨나요?"}
rows[#rows+1]={"A little busy here, $c.  What d'ye want?","지금 조금 바쁩니다, $c님. 뭘 도와드릴까요?"}
rows[#rows+1]={"A little help here? Or do you need more training, $N?$B$BI'm kinda busy at the moment if you hadn't noticed.","여기 좀 도와주겠어? 훈련을 더 받고 싶어, $n?$B$B눈치 못 챘나 본데, 지금 좀 바쁘거든."}
rows[#rows+1]={"A little help here? Or do you need more training, $n?$B$BI'm kinda busy at the moment if you hadn't noticed.","여기 좀 도와주겠어? 훈련을 더 받고 싶어, $n?$B$B눈치 못 챘나 본데, 지금 좀 바쁘거든."}
rows[#rows+1]={"A man can only live with himself and his shame for so long, $c, before he must take action to undo the mistakes he's made.","$c|1이여;여;, 자신이 저지른 실수를 만회하지 않는 한 일평생을 수치스럽게 살아갈 수밖에 없소."}
rows[#rows+1]={"A miner?  Ye don't need to ask if $glad : lass;, only where!  Yarr is who yer looking for, and I think ye can find him hiding out over in Steelgrill's Depot.","광부가 있느냐고 물었습니까? 있냐, 없냐가 아니라, 어디로 가야 하는지 물어봐야지요, 젊은 $C 양반! 얄을 찾아가십시오. 아마 스틸그릴의 정비소에 있을 겁니다."}
rows[#rows+1]={"A strong weapon is no good if you don't live long enough to wield it, $c.","아무리 좋은 무기라도 그걸 쓸 만큼 오래 살지 않으면 아무 소용없지, $c."}
rows[#rows+1]={"A thick red slash has been drawn across the words WANTED: Deathclaw.  \"This bounty has been claimed by the heroic $N, who has overcome the fearsome beast,\" declares more writing in the same red ink.","현상 수배: 죽음의 발톱이라는 단어 위에 두꺼운 붉은색 사선이 그려져 있습니다. 똑같은 붉은색 잉크로 \"$n|1이라는;라는; 영웅이 무시무시한 야수를 해치우고 현상금을 차지했습니다.\"라는 문구와 함께 다른 내용이 적혀 있습니다."}
rows[#rows+1]={"A thick red slash has been drawn across the words WANTED: Deathclaw.  \"This bounty has been claimed by the heroic $n, who has overcome the fearsome beast,\" declares more writing in the same red ink.","현상 수배: 죽음의 발톱이라는 단어 위에 두꺼운 붉은색 사선이 그려져 있습니다. 똑같은 붉은색 잉크로 \"$n|1이라는;라는; 영웅이 무시무시한 야수를 해치우고 현상금을 차지했습니다.\"라는 문구와 함께 다른 내용이 적혀 있습니다."}
rows[#rows+1]={"A thousand curses upon you, $r!  This prison will not hold me for long!","저주를 퍼부어주마, $r! 나를 오래 붙잡아 두지는 못할 것이다!"}
rows[#rows+1]={"A very good question, $c. When last I had heard, the Alliance had managed to smelt $1997w out of $1998w copper bars, $2002w out of $2003w iron bars and $2011w out of $2012w thorium bars needed for the war effort.","아주 좋은 질문이군. 내가 마지막으로 듣기로, 얼라이언스는 전쟁에 필요한 구리 주괴 $1998w개 중 $1997w개, 철 주괴 $2003w개 중 $2002w개, 그리고 토륨 주괴 $2012w개 중 $2011w개를 모았다네."}
rows[#rows+1]={"A warlock, eh...  Well, if you've got a mind to be doing that sort of thing around here then ye best keep yer demons on a leash $gboyo : girlie;.  I don't like demons, but I love putting mah axe to them.  Ye get me?  \010Now you just leave me be and go get lost in The Forlorn Cavern.  That's where you'll find that warlock, Thistleheart.","흑마법사라... 글쎄, 여기서 그런 일을 할 생각이라면 당신의 악마를 잘 관리하는 게 좋을 겁니다, 젊은 분. 전 악마를 좋아하지도 않습니다. 제 도끼로 악마들을 내리치는 걸 훨씬 좋아합니다. 무슨 말인지 아시겠습니까?\010쓸쓸한 뒷골목으로 어서 가십시오. 거기서 시슬하트라는 흑마법사를 만날 수 있을 테니까요."}
rows[#rows+1]={"A warlock, eh...  Well, if you've got a mind to be doing that sort of thing around here then ye best keep yer demons on a leash $gboyo : girlie;.  I don't like demons, but I love putting mah axe to them.  Ye get me?  $B$BNow you just leave me be and go get lost in The Forlorn Cavern.  That's where you'll find that warlock, Thistleheart.","흑마법사라... 글쎄, 여기서 그런 일을 할 생각이라면 당신의 악마를 잘 관리하는 게 좋을 걸, 젊은 양반. 난 악마를 좋아하지도 않아. 내 도끼로 악마들을 내리찍는 걸 훨씬 좋아하지. 무슨 말인지 알겠나?$b$b쓸쓸한 뒷골목으로 냉큼 가버리게. 거기서 시슬하트라는 흑마법사를 만날 수 있을 테니."}
rows[#rows+1]={"A wedding, eh? If that doesn't bring this bunch together, I'll eat my hammer!$B$BWe need to make sure this wedding is spectacular, $N, and we're going to need your help. There's an old Wildhammer saying... let me think... how does it go?","결혼이라고요? 두 가문이 결혼으로 맺어지고도 화해하지 못한다면 제 망치를 먹겠습니다!$B$B이번 결혼식은 최고로 멋지게 치러야 합니다, $n 님. 그러려면 당신 도움이 필요하고요. 와일드해머 속담에 이런 말이 있죠... 잠깐만요... 어떻게 시작하더라?"}
rows[#rows+1]={"A wedding, eh? If that doesn't bring this bunch together, I'll eat my hammer!$B$BWe need to make sure this wedding is spectacular, $n, and we're going to need your help. There's an old Wildhammer saying... let me think... how does it go?","결혼이라고요? 두 가문이 결혼으로 맺어지고도 화해하지 못한다면 제 망치를 먹겠습니다!$B$B이번 결혼식은 최고로 멋지게 치러야 합니다, $n 님. 그러려면 당신 도움이 필요하고요. 와일드해머 속담에 이런 말이 있죠... 잠깐만요... 어떻게 시작하더라?"}
rows[#rows+1]={"A wondrous Winter Veil to you... uh... little $G boy : girl;.  Good children get special, um, discounts at any local Smokywood Pastures vendor.  Yum.","귀여운 우리 친구! 즐거운 겨울맞이 되세요... 착한 와우저 어린이들이라면 굴뚝나무 목장조합에서 특별한 물품을 할인된 가격에 구입할 수 있어요. 음... 생각만 해도 군침 도는 음식들이 다양하게 준비되어 있답니다."}
rows[#rows+1]={"A-ten-hut! All Ahn'Qiraj war materiel accounted for and in the process of being transported to Cenarion Hold $g sir : ma'am;! I am told that the last of it should arrive in less than $2113w days. Once that is done, and someone rings that gong over there to open the gates, I guarantee that we'll give those bugs one heck of a fight!","차렷! 안퀴라즈 전쟁에 필요한 전쟁 물자 수집이 완료되었으며 현재 세나리온 요새로 수송 중입니다! $2113w일 내로 마지막 물자가 도착할 예정이라고 합니다. 수송이 완료되고 누군가 그곳의 징을 울려 성문을 열면 우리는 벌레 놈들을 한 방에 날려 버릴 것입니다. 자신 있습니다!"}
rows[#rows+1]={"About twenty years ago, the Alliance launched the first Expedition to this world in hopes of eradicating the orcs forever. It was a... terrible conflict. Many brave souls perished to assure Azeroth's safety.$B$BThank you, $N, for helping those souls find peace.","약 20년 전 얼라이언스는 오크들을 완전히 뿌리 뽑을 생각으로 이 세계에 첫 번째 원정대를 보냈소. 정말... 끔찍한 싸움이었지. 수많은 영혼이 아제로스의 안전을 위해 용감하게 싸우다 사라져 갔소이다.$B$B그런 영혼들에게 안식을 가져다줘서 정말 고맙소이다, $n."}
rows[#rows+1]={"About twenty years ago, the Alliance launched the first Expedition to this world in hopes of eradicating the orcs forever. It was a... terrible conflict. Many brave souls perished to assure Azeroth's safety.$B$BThank you, $n, for helping those souls find peace.","약 20년 전 얼라이언스는 오크들을 완전히 뿌리 뽑을 생각으로 이 세계에 첫 번째 원정대를 보냈소. 정말... 끔찍한 싸움이었지. 수많은 영혼이 아제로스의 안전을 위해 용감하게 싸우다 사라져 갔소이다.$B$B그런 영혼들에게 안식을 가져다줘서 정말 고맙소이다, $n."}
rows[#rows+1]={"Ach, it's hard enough keeping order around here without all these new troubles popping up!  I hope you have good news, $N...","어이쿠, 이렇게 자꾸 새로운 문제가 발생해서는 이곳 주위의 질서를 바로잡기가 어렵습니다! $n, 당신이 좋은 소식을 가져왔으면 좋겠군요..."}
rows[#rows+1]={"Ack!  Stay back, $r!","악! $r|1이잖아;잖아;, 물러서!"}
rows[#rows+1]={"Ack, ye've been busy now haven't ye?!  I canna thank ye enough for bombing them demons and resupplying us with mounts.$B$BYer making our job all the more easier.  Keep up the good work, $g laddy : lassie;!","어이쿠, 당신 요즘 바쁘지 않소? 악마들의 포탄 더미를 없애고 새로운 탈것을 보충해 준 점에 대해서 뭐라고 감사해야 할지 모르겠다오.$B$B당신이 우리 일을 무척 쉽게 풀어주고 있다오. 계속 잘해주시기 바라오, 친구!"}
rows[#rows+1]={"Aessina is the spirit of nature, my everlasting companion in both this world and the dream beyond. Her shrine in western Hyjal is at the forefront of the Twilight offensive, and may be ablaze this very moment.$B$B$N, we will never restore Mount Hyjal without Aessina's help. Save her shrine from the fires, and save the nearby animals threatened by the blaze. We must do this or the entire mountain is lost.","아에시나는 자연의 혼이며, 이 세계와 그너머 꿈속 세계에서도 나와 함께하는 영원한 친구이다. 하이잘 서쪽 지역에 그녀의 제단이 있는데, 지금 황혼의 망치단의 집중 공격을 받고 있다. 지금 이 순간에도 불타고 있을지 모른다.$B$B$n, 아에시나의 도움 없이는 절대 하이잘 산을 되찾을 수 없다. 그녀의 제단을 화재로부터 구해내고, 화재로 겁에 질린 제단 주변의 동물들도 구해 주거라. 그렇게 하지 않으면 산 전체를 잃게 될 것이다."}
rows[#rows+1]={"Aessina is the spirit of nature, my everlasting companion in both this world and the dream beyond. Her shrine in western Hyjal is at the forefront of the Twilight offensive, and may be ablaze this very moment.$B$B$n, we will never restore Mount Hyjal without Aessina's help. Save her shrine from the fires, and save the nearby animals threatened by the blaze. We must do this or the entire mountain is lost.","아에시나는 자연의 혼이며, 이 세계와 그너머 꿈속 세계에서도 나와 함께하는 영원한 친구이다. 하이잘 서쪽 지역에 그녀의 제단이 있는데, 지금 황혼의 망치단의 집중 공격을 받고 있다. 지금 이 순간에도 불타고 있을지 모른다.$B$B$n, 아에시나의 도움 없이는 절대 하이잘 산을 되찾을 수 없다. 그녀의 제단을 화재로부터 구해내고, 화재로 겁에 질린 제단 주변의 동물들도 구해 주거라. 그렇게 하지 않으면 산 전체를 잃게 될 것이다."}
rows[#rows+1]={"After zhat ritual debacle, you owe me, $r.$b$bAnd I plan on collectink!","의식이 그렇게 엉망으로 끝났으니, 넌 내게 큰 빚을 졌어, $r.$b$b그리고 난 받을 빚은 잊지 않는 사람이거든!"}
rows[#rows+1]={"Agamath, the First Gate is breached and two of Kil'jaeden's lieutenants, Lady Sacrolash and Grand Warlock Alythess, must be destroyed.$B$BGather your friends, $c, and see to it! Rohendor, the Second Gate is our next target.","첫 번째 관문인 아가마스를 돌파했고 킬제덴의 두 부관인 여군주 사크로래쉬와 대흑마법사 알리테스를 처치해야 합니다.$B$B$c|1이여;여;, 당신의 친구들과 함께 가서 도와주십시오! 두 번째 관문인 로헨도르가 우리의 다음 과제입니다."}
rows[#rows+1]={"Ah - oddities and rarities. We specialize in Azeroth's more unique items for the discerning adventurer.$B$BSince you're speaking with me, you must already have an idea of what you're looking for. So, $N, which item are you interested in?","아... 신기하고 진귀한 물건 말이로군. 우린 안목 있는 여행자들을 위한 아제로스의 희귀한 물건들을 전문으로 취급하지.$B$B이렇게 나를 찾아온 걸 보니 자넨 찾는 물건이 있는 게로군. 자, $n, 어떤 물건에 관심이 있나?"}
rows[#rows+1]={"Ah - oddities and rarities. We specialize in Azeroth's more unique items for the discerning adventurer.$B$BSince you're speaking with me, you must already have an idea of what you're looking for. So, $n, which item are you interested in?","아... 신기하고 진귀한 물건 말이로군. 우린 안목 있는 여행자들을 위한 아제로스의 희귀한 물건들을 전문으로 취급하지.$B$B이렇게 나를 찾아온 걸 보니 자넨 찾는 물건이 있는 게로군. 자, $n, 어떤 물건에 관심이 있나?"}
rows[#rows+1]={"Ah good, there $g he : she; is... my future $g master : mistress; of the elements! What kind of training would you like today?","아, 좋아. 앞으로 내가 정령의 대가로 키울 $g젊은이:아가씨;가 여기 왔군! 오늘은 무슨 훈련을 받고 싶으신가?"}
rows[#rows+1]={"Ah yes, I have read of you, $N.","아... 그렇지, 자네에 대한 글을 읽은 적이 있네, $n."}
rows[#rows+1]={"Ah yes, I have read of you, $n.","아... 그렇지, 자네에 대한 글을 읽은 적이 있네, $n."}
rows[#rows+1]={"Ah, $N - it is good to see you again.  I trust your affairs go well.","오, $n 님! 다시 만나서 반가워요. 그동안 잘 지내셨죠?"}
rows[#rows+1]={"Ah, $N!  You're just the person I was hoping to see!  We have enough supplies to send a ground assault against the Horde!  Field Marshal Teravaine is waiting in the Field of Strife for orders...$B$BYou're a brave veteran who's proven himself time and again.  Do you want to deliver Teravaine the orders?","아, $n! 마침 자네 같은 이를 찾고 있던 중이었네! 이제 보급품이 충분히 모여서 호드에 맞설 지상 공격 부대를 출격시킬 수 있어! 투쟁의 벌판에서 테라베인 야전사령관이 명령서를 기다리고 있을 걸세.$B$B자네는 수 차례 자기 자신의 가치를 몸소 입증해 보인 노련한 용사이니 테라베인에게 명령서를 전달해 주지 않겠나?"}
rows[#rows+1]={"Ah, $N! A little bird told me you would be coming.$B$BThat's how Aviana sends messages around.","아, $n! 당신이 온다는 소식을 작은 새에게 전해 들었소.$B$B아비아나 님은 이렇게 소식을 전달하신다오."}
rows[#rows+1]={"Ah, $c, good to see you. We need assistance here with gathering supplies in preparation for the impending war at Ahn'Qiraj. I've been asked to put together a great many first aid field kits, and the primary component I need is wool bandages. I already have some, $2079w to be exact, but I need to collect $2080w.","$c|1이여;여;, 만나서 반갑네. 우리는 다가올 안퀴라즈 전쟁에 필요한 물자를 모으고 있는데 자네의 도움이 필요하네. 내가 맡은 일은 응급치료 물품 중에서 양모 붕대를 대량 모으는 것이라네. 지금 정확하게 $2079w개 가지고 있는데 총 $2080w개가 필요하다네."}
rows[#rows+1]={"Ah, $n - it is good to see you again.  I trust your affairs go well.","오, $n 님! 다시 만나서 반가워요. 그동안 잘 지내셨죠?"}
rows[#rows+1]={"Ah, $n!  You're just the person I was hoping to see!  We have enough supplies to send a ground assault against the Horde!  Field Marshal Teravaine is waiting in the Field of Strife for orders...$B$BYou're a brave veteran who's proven himself time and again.  Do you want to deliver Teravaine the orders?","아, $n! 마침 자네 같은 이를 찾고 있던 중이었네! 이제 보급품이 충분히 모여서 호드에 맞설 지상 공격 부대를 출격시킬 수 있어! 투쟁의 벌판에서 테라베인 야전사령관이 명령서를 기다리고 있을 걸세.$B$B자네는 수 차례 자기 자신의 가치를 몸소 입증해 보인 노련한 용사이니 테라베인에게 명령서를 전달해 주지 않겠나?"}
rows[#rows+1]={"Ah, $n! A little bird told me you would be coming.$B$BThat's how Aviana sends messages around.","아, $n! 당신이 온다는 소식을 작은 새에게 전해 들었소.$B$B아비아나 님은 이렇게 소식을 전달하신다오."}
rows[#rows+1]={"Ah, $n, don't cry. Lucky for you, when last you gave me the amulet, I attuned myself to it. I'll just summon it back from wherever you dropped it.$B$BTry looking in your bags now.","아, $n. 다행스럽게도 당신이 지난번 내게 아뮬렛을 주었을 때, 나 자신을 아뮬렛에 맞추어 놓았답니다. 당신이 잃어버린 장소에 관계없이 다시 소환해 드릴 수 있단 말이죠.$B$B자, 이제 소지품을 한 번 살펴보세요."}
rows[#rows+1]={"Ah, $r... I possess great knowledge a' da world and how ta create charms a' great power. ","아, 저는 이 세계의 많은 지식을 알고 있습니다. 강력한 힘을 지닌 부적을 만드는 법도 안답니다."}
rows[#rows+1]={"Ah, I see what kind of $c you are, $N! Now then, the second verse is all about Fanny and Firebeard getting together.$B$BWhat rhymes with \"Professed?\"","아, 당신이 어떤 $c인지 알겠군요, $n 님! 자, 두 번째 소절은 패니와 파이어비어드의 결합에 관한 내용입니다.$B$B\"고백\"와 운이 맞는 단어 없을까요?"}
rows[#rows+1]={"Ah, I see what kind of $c you are, $n! Now then, the second verse is all about Fanny and Firebeard getting together.$B$BWhat rhymes with \"Professed?\"","아, 당신이 어떤 $c인지 알겠군요, $n 님! 자, 두 번째 소절은 패니와 파이어비어드의 결합에 관한 내용입니다.$B$B\"고백\"와 운이 맞는 단어 없을까요?"}
rows[#rows+1]={"Ah, a fellow warlock who has proven $ghis:her; worth to some degree.$B$BI am pleased to meet your acquaintance. My name is Menara Voidrender... and not without just cause.$B$BYou seem powerful and well-learned enough that other tools... more powerful tools... would be welcome and not foolishly imparted. If this is true, then speak to me further. If not, well then, you know your way  back to the docks and off into the ocean.","아, 어느 정도 자신의 가치를 입증한 흑마법사 동료로군요.$B$B만나게 돼서 반가워요. 나는 미네라 보이드렌더라고 해요. 이런 이름을 지은 데는 다 그만한 이유가 있죠.$B$B당신은 강한 새 도구들에 쉽게 적응하고 어리석게 남에게 줘 버리지 않을 정도의 상식은 있는 것 같군요. 그렇다면 다시 나와 얘기를 하도록 해요. 아니면 전투는커녕 부둣가로 돌아가서 다시 고향으로 돌아가 편히 사시는 게 좋을 거예요."}
rows[#rows+1]={"Ah, a new champion to aid our cause? What say you, $N? $B","오, 우리 일을 돕기 위해 새로 온 용사인가? $n, 무슨 일로 왔는지 말해 보게나."}
rows[#rows+1]={"Ah, a new champion to aid our cause? What say you, $n? \010","오, 우리 일을 돕기 위해 새로 온 용사인가? $n, 무슨 일로 왔는지 말해 보게나."}
rows[#rows+1]={"Ah, another $c looking to be a gladiator, eh? Good!\010I sell the arena team charters you'll need to participate in ranking Steamwheedle Fighting Circuit matches.","아, 또 다른 $c|1이;가; 검투사가 되려고 왔군? 좋아!\010스팀휘들 결투 대회의 순위 경기에 참가하려면 반드시 내가 파는 투기장 팀 창단허가서에 서명하고 팀을 구성해야 한다네."}
rows[#rows+1]={"Ah, another $c looking to be a gladiator, eh? Good!$B$BI sell the arena team charters you'll need to participate in ranking Steamwheedle Fighting Circuit matches.","아, 또 다른 $c|1이;가; 검투사가 되려고 왔군? 좋아!\010\010스팀휘들 결투 대회의 순위 경기에 참가하려면 반드시 내가 파는 투기장 팀 창단허가서에 서명하고 팀을 구성해야 한다네."}
rows[#rows+1]={"Ah, good ol' Brandur Ironhammer.  There's no doubt he'll provide ye with the guidance ye seek, $glad : lass;.  Ye'll find him in the Hall of Mysteries north of the gates of Ironforge.","아! 브란두르 아이언해머를 찾는군요. 그에게 가면 분명 도움을 받을 수 있을 겁니다. 아이언포지 성문에서 북쪽으로 가십시오. 신비의 전당에 있을 겁니다."}
rows[#rows+1]={"Ah, hello there, $r. As you can see, I'm not open for business quite yet. Now, if you'll excuse me, I'm very busy.","$r|1이여;여;, 참 반갑군. 자네도 알다시피 아직 장사 개시 전일세. 그럼 바빠서 이만 실례!"}
rows[#rows+1]={"Ah, here's the $g hero : heroine; of the hour now! Good to see you again, $N! I trust that you're still destroying the Scourge wherever you find them?","아, 오늘의 $g 영웅:여걸;께서 오셨군! 다시 만나서 반갑습니다, $N! 아직도 스컬지가 보이는 족족 박살 내고 계시겠죠?"}
rows[#rows+1]={"Ah, here's the $g hero : heroine; of the hour now! Good to see you again, $n! I trust that you're still destroying the Scourge wherever you find them?","아, 영웅이 오셨군요! $n, 다시 만나서 반갑습니다! 지금도 스컬지를 보이는 대로 해치우고 있겠지요?"}
rows[#rows+1]={"Ah, it's you, $N! Welcome into our sanctuary. Rest and refresh yourself; you have more than earned it.","아 그대였군요, $n! 저희 성소에 오시다니 반갑습니다. 쉬시면서 기운을 회복하시지요. 생각보다 훨씬 편하실 겁니다."}
rows[#rows+1]={"Ah, it's you, $n! Welcome into our sanctuary. Rest and refresh yourself; you have more than earned it.","아 그대였군요, $n! 저희 성소에 오시다니 반갑습니다. 쉬시면서 기운을 회복하시지요. 생각보다 훨씬 편하실 겁니다."}
rows[#rows+1]={"Ah, one of my favorite customers. You look to be of a warlock of some power, $N. I am pleased to meet you. If there is anything I can do for you, please, just ask.$B$BMy brother and I feel that it will be your kind who lead us into the next great era. One with such power... such control... it's only a matter of time before the Legion itself bends to your will.$B$BI am but a little envious.","아, 내가 제일 좋아하는 손님이로군. 당신은 꽤 강한 흑마법사 같네. 만나서 반가우이. 혹시 내가 해 줄 수 있는 일이라도 있으면 말만 하게.$B$B우리 형제들은 당신과 같은 부류의 이들이 다음 세대를 이끌어 줄 것이라 믿고 있지. 그렇게나 큰 힘을 가진 이라면 불타는 군단이 무릎을 꿇는 것도 시간문제일 뿐이야.$B$B아주 부럽소이다."}
rows[#rows+1]={"Ah, one of my favorite customers. You look to be of a warlock of some power, $n. I am pleased to meet you. If there is anything I can do for you, please, just ask.$B$BMy brother and I feel that it will be your kind who lead us into the next great era. One with such power... such control... it's only a matter of time before the Legion itself bends to your will.$B$BI am but a little envious.","아, 내가 제일 좋아하는 손님이로군. 당신은 꽤 강한 흑마법사 같네. 만나서 반가우이. 혹시 내가 해 줄 수 있는 일이라도 있으면 말만 하게.$B$B우리 형제들은 당신과 같은 부류의 이들이 다음 세대를 이끌어 줄 것이라 믿고 있지. 그렇게나 큰 힘을 가진 이라면 불타는 군단이 무릎을 꿇는 것도 시간문제일 뿐이야.$B$B아주 부럽소이다."}
rows[#rows+1]={"Ah, to be young again, and to have discovered potions for the first time. Thank you for refreshing my memory, $N. Now go share that youthful enthusiasm with Milla Fairancora over there.","아, 젊음이란... 물약을 처음 접했을 때는 또 어떻고... 기억을 상기시켜줘서 고맙습니다. 이제 저기에 있는 밀라 페어랜코라와 젊은 열정을 나누어 보세요."}
rows[#rows+1]={"Ah, to be young again, and to have discovered potions for the first time. Thank you for refreshing my memory, $n. Now go share that youthful enthusiasm with Milla Fairancora over there.","아, 젊음이란... 물약을 처음 접했을 때는 또 어떻고... 기억을 상기시켜줘서 고맙습니다. 이제 저기에 있는 밀라 페어랜코라와 젊은 열정을 나누어 보세요."}
rows[#rows+1]={"Ah, um, yes $g sir : ma'am;. It would appear that we have collected all of the medium leather that the Alliance feels is necessary for the war. I'm told that there may be others here though that still need your assistance with their collection efforts.","아, 네, 그렇습니다. 얼라이언스 연합에서 전쟁을 수행하는 데 필요한 일반 가죽을 모두 모은 것 같습니다. 다른 물자를 모으는 곳에서 당신의 도움을 필요로 할지 모른다는 말을 드리고 싶군요."}
rows[#rows+1]={"Ah, you must be the $glad : lass; assigned to show me around the Eversong Woods.  Took your sweet time getting here, didn't you?$B$BVery well, off we go.  Let us not waste one more minute.","아, 당신이 바로 나에게 영원노래 숲을 안내하는 임무를 맡은 자로군. 여기까지 오는 동안 귀한 시간을 허비하지는 않았소?$B$B좋아, 출발하지. 일 분도 더 허비해서는 안 되겠어."}
rows[#rows+1]={"Aha! Good day, good day, Master $C! Come, sit down and have a drink. You have an enterprising look in your eye, and I think you'll find speaking to me worth your time....","아하! 좋은 날이군, 좋은 날이야, $C 님! 어서 와서 앉고 한잔하게. 눈빛을 보니 장사 수완이 좀 있어 보이는데, 나랑 이야기해 두면 시간 아깝진 않을 걸세..."}
rows[#rows+1]={"Ahh! There you are, $n.$b$bI must speak with you at once.","아! 거기 계셨군요, $n 님.$b$b지금 당장 대화할 것이 있습니다."}
rows[#rows+1]={"Ahh, a fresh face! Welcome to Coldhewn Camp. We skin what we hunt, and we cut what we burn—keeps the coin flowin’ and the ale cold.$B$BPlenty o’ wolves and hares in these hills, and their pelts fetch a fine price in Ironforge. But keep yer eyes open—there’s been new tracks in the snow. Big ones. Clawed and deep.$B$BSome say it’s a rogue yeti, others swear it’s a frost elemental gone feral. But a trapper came down from the ridge, white as bone, swearing he saw a great sabercat—pale as the drifts, eyes like cold fire.$B$BThey call it Icehide, though no one's been fool enough to get close. If ye go wanderin’, $N, keep a sharp blade… and sharper senses.","콜드헤운 캠프에 오신 것을 환영합니다. 사냥하는 것을 벗고, 태우는 것을 잘라서 동전이 흐르고 맥주도 차가워집니다.$B$B이 언덕에 많은 늑대와 토끼, 그들의 가죽은 좋은 가격을 가져 아이언포지눈은 새 틈이 많고, 큰 틈이 깊어$B$B어떤 사람들은 이티가  ⁇ 이라고 말하지만 다른 사람들은 얼음의 원자물이 야생으로 사라졌다고 맹세합니다. 하지만 한 사냥꾼은  ⁇ 에서 내려왔고, 뼈처럼 흰색으로, 그는 큰  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 을  ⁇ 을 보며, 눈은 차가운 불처럼 보였다.$B$B아이스하이드라고 부르지만 아무도 가까이 갈 만큼 멍청하지 않았어 $N날카로운 칼을 가지고... 그리고 더 날카로운 감각을 유지하십시오."}
rows[#rows+1]={"Ahoy, $N! Not a pretty picture, is it?$B$BThe Horizon Scout at the bottom of the sea, my crew in shambles, and our cargo and passengers strewn about like so much debris that you'd think this was one of Stormwind's canals after a festival.$B$BAnd that's not where the trouble ends...","$c|1이여;여;, 마침 잘 오셨어요! 그리 보기 좋은 광경은 아니죠?$B$B지평선 정찰함은 바다 밑바닥으로 가라앉아 버렸고, 살아남은 선원들은 모두 녹초가 돼버렸어요. 거기다 승객들의 짐과 화물의 잔해가 잔뜩 널려 있으니 꼭 축제가 끝난 뒤 너저분한 스톰윈드의 운하를 바라보는 듯한 기분이 들 거예요.$B$B게다가 위험천만한 일이 또 남아 있으니..."}
rows[#rows+1]={"Ahoy, $N! Pete Arr, Plunder Trade Representative. On the PTR me plunder be free for the taking.","안녕하세요 $N피트 어, 약탈 무역 대표."}
rows[#rows+1]={"Ahoy, $n! Not a pretty picture, is it?$B$BThe Horizon Scout at the bottom of the sea, my crew in shambles, and our cargo and passengers strewn about like so much debris that you'd think this was one of Stormwind's canals after a festival.$B$BAnd that's not where the trouble ends...","$c|1이여;여;, 마침 잘 오셨어요! 그리 보기 좋은 광경은 아니죠?$B$B지평선 정찰함은 바다 밑바닥으로 가라앉아 버렸고, 살아남은 선원들은 모두 녹초가 돼버렸어요. 거기다 승객들의 짐과 화물의 잔해가 잔뜩 널려 있으니 꼭 축제가 끝난 뒤 너저분한 스톰윈드의 운하를 바라보는 듯한 기분이 들 거예요.$B$B게다가 위험천만한 일이 또 남아 있으니..."}
rows[#rows+1]={"Al'tha, Al'tha bormaz. Ni bormaz ta'thall? It comes, it walks in flames, $r!","알다, 알다, 보르마즈, 니 보르마즈 타달? 옵니다, 불속을 걸어 옵니다, $r|1이여;여;!"}
rows[#rows+1]={"Alas $N, I am much too busy to talk.  As I mentioned, I need time to think on the situation at hand.$B$BI wish you luck in your travels.  Good day.","이런, $n! 너무 바빠서 얘기를 나눌 시간도 없군요. 말씀드린 것처럼 곧 닥칠 상황에 대해 생각할 시간이 필요합니다.$B$B그대의 여정에 행운이 함께하기를 바랍니다. 좋은 하루 되십시오."}
rows[#rows+1]={"Alas $N, I am much too busy to talk. As I mentioned, I need time to think on the situation at hand.$B$BI wish you luck in your travels. Good day.","미안하네, $N. 지금은 너무 바빠서 이야기할 여유가 없군. 말했듯이 현재 상황을 좀 생각해 볼 시간이 필요해.$B$B여행에 행운이 따르길 바라네. 좋은 하루 보내게."}
rows[#rows+1]={"Alas $c, you are not considered to be exalted to Darnassus and the night elves of Teldrassil.  Only when you prove yourself to us through deeds - not just mere words - will I then make available my selection of mounts for your perusal.","안타깝게도 다르나서스와 텔드랏실의 나이트 엘프는 그대를 같은 편으로 생각하지 않는군요. 말이 아닌 행동으로 그대가 우리 나이트 엘프의 친구라는 것을 증명해 보인 후에만 제가 판매하는 탈것을 그대에게 보여드릴 수 있습니다."}
rows[#rows+1]={"Alas $n, I am much too busy to talk.  As I mentioned, I need time to think on the situation at hand.$B$BI wish you luck in your travels.  Good day.","이런, $n! 너무 바빠서 얘기를 나눌 시간도 없군요. 말씀드린 것처럼 곧 닥칠 상황에 대해 생각할 시간이 필요합니다.$B$B그대의 여정에 행운이 함께하기를 바랍니다. 좋은 하루 되십시오."}
rows[#rows+1]={"All barriers are now down, $N! Only Sindragosa stands between the Lich King and us. Justice comes soon...","장벽이 모두 무너졌네, $n! 신드라고사만이 리치 왕과 우리 사이에 있을 뿐이야. 정의는 곧 실현될 걸세..."}
rows[#rows+1]={"All barriers are now down, $n! Only Sindragosa stands between the Lich King and us. Justice comes soon...","장벽이 모두 무너졌네, $n! 신드라고사만이 리치 왕과 우리 사이에 있을 뿐이야. 정의는 곧 실현될 걸세..."}
rows[#rows+1]={"All has been gathered and is being sent to Silithus, $c. It should get there within $2113w days. I can only hope that after the gong is rung, and the gates opened, that our efforts here will make an impact and save many lives.","모든 물자 수집을 끝마치고 실리더스로 옮기는 중이네. $2113w일 내로 모든 물자가 도착할 걸세. 징이 울린 후 관문이 열리면, 그동안의 우리의 노력이 생명을 구하고 많은 도움을 줄 수 있기를 바랄 뿐이네."}
rows[#rows+1]={"All is completed, young $c. Even as we speak, both the Horde and the Alliance are in the process of transporting all final goods for the war into Silithus near Cenarion Hold, which should be complete in less than $2113w days. After that, the gong near the gates of Ahn'Qiraj can be rung, and the war will begin.","젊은 $c|1이여;여;, 모든 준비가 끝났습니다. 일전에 우리가 말한 대로 호드와 얼라이언스 모두 전쟁 물자를 세나리온 요새 근처의 실리더스로 수송하고 있지요. 최종 작업은 늦어도 $2113w일 내에 완료될 겁니다. 그다음 안퀴라즈 관문 근처의 징이 울리면 전쟁이 시작되는 겁니다."}
rows[#rows+1]={"All is gathered, $c. All is being transported for final preparation to Silithus and should arrive within $2113w days. All of our combined forces await the $g hero : heroine; that will complete the reunification of the Scepter of the Shifting Sands, ring the gong and begin the Ahn'Qiraj War.","물자 수집을 모두 완료했소. 마지막 준비를 위해 실리더스로 수송 중인데 $2113w일 내로 도착할 예정이오. 우리 연합군은 지금 흐르는 모래의 홀을 하나로 결합하여 징을 울려 안퀴라즈 전쟁을 시작할 영웅을 기다리고 있소."}
rows[#rows+1]={"All members of the Horde are equal in my eyes, $N. We have all suffered many burdens, and if it were not for wisdom and honor, then we would be no better than the Scourge or my people while our blood was tainted by the demon Mannoroth.$B$BIt is your duty to aid the Horde and to defend our way of life. But it is also your duty to know when quarter and compassion should be given to friend and foe alike.$B$BUnderstand this well. This is the new Horde, not some demon-spawned army who lack freewill.","이 스랄의 앞에서 호드의 만백성들은 평등하도다. 우리는 힘든 시기를 함께 해왔다. 명예, 그리고 지혜가 없었더라면 악마 만노로스에 의해 우리의 피는 더럽혀지고 스컬지와 다를 바 없는 신세가 되었으리라.$B$B너의 임무는 호드를 돕고 우리 오크족을 수호하는 것이다. 그리고 적군에게도 자비와 관대함을 보여야 하는 시기를 알아내는 것도 너의 임무다.$B$B이 점을 명심해라. 이제 우리는 자유 의지를 빼앗긴 악마의 군대가 아니라 새로운 시대의 호드로 거듭났도다"}
rows[#rows+1]={"All members of the Horde are equal in my eyes, $n. We have all suffered many burdens, and if it were not for wisdom and honor, then we would be no better than the Scourge or my people while our blood was tainted by the demon Mannoroth.$B$BIt is your duty to aid the Horde and to defend our way of life. But it is also your duty to know when quarter and compassion should be given to friend and foe alike.$B$BUnderstand this well. This is the new Horde, not some demon-spawned army who lack freewill.","이 스랄의 앞에서 호드의 만백성들은 평등하도다. 우리는 힘든 시기를 함께 해왔다. 명예, 그리고 지혜가 없었더라면 악마 만노로스에 의해 우리의 피는 더럽혀지고 스컬지와 다를 바 없는 신세가 되었으리라.$B$B너의 임무는 호드를 돕고 우리 오크족을 수호하는 것이다. 그리고 적군에게도 자비와 관대함을 보여야 하는 시기를 알아내는 것도 너의 임무다.$B$B이 점을 명심해라. 이제 우리는 자유 의지를 빼앗긴 악마의 군대가 아니라 새로운 시대의 호드로 거듭났도다."}
rows[#rows+1]={"All of Illidan's lieutenants have fallen, $N.  The way forward is open, if you're ready.","일리단의 모든 부관들이 죽었습니다, $n. 앞으로 나아갈 길이 열렸으니 준비되셨으면 어서 가십시오."}
rows[#rows+1]={"All of Illidan's lieutenants have fallen, $n.  The way forward is open, if you're ready.","일리단의 모든 부관들이 죽었습니다, $n. 앞으로 나아갈 길이 열렸으니 준비되셨으면 어서 가십시오."}
rows[#rows+1]={"All right, $c. You think you have what it takes to make it in the Steamwheedle Fighting Circuit's arena battlegrounds?","좋아! 자네는 스팀휘들 결투 대회가 열리는 투기장에서 싸울 준비가 된 것 같군그래."}
rows[#rows+1]={"All the roguish types hang out in The Forlorn Cavern, north of the gates of Ironforge.  I'd wager ye'll find Fenthwick there, no doubt counting the coin of another cut purse.  I'll catch him one of these days!  \010In the meantime I'll have my eye on you as well, $glad : lass;.","도적 친구들이라면 아이언포지 성문에서 북쪽에 있는 쓸쓸한 뒷골목에 있습니다. 그곳에 가면 분명히 펜스윅이 다른 소매치기 친구들에게 훔친 돈을 세고 있을 테지요. 조만간 그들을 모조리 잡아들일 생각입니다! 물론 그동안 당신도 지켜볼 겁니다."}
rows[#rows+1]={"All the roguish types hang out in The Forlorn Cavern, north of the gates of Ironforge.  I'd wager ye'll find Fenthwick there, no doubt counting the coin of another cut purse.  I'll catch him one of these days!  $B$BIn the meantime I'll have my eye on you as well, $glad : lass;.","도적 친구들이라면 아이언포지 성문에서 북쪽에 있는 쓸쓸한 뒷골목에 있습니다. 그곳에 가면 분명히 펜스윅이 다른 소매치기 친구들에게 훔친 돈을 세고 있을 테지요. 조만간 그들을 모조리 잡아들일 생각입니다! 물론 그동안 당신도 지켜볼 겁니다."}
rows[#rows+1]={"All this fighting is finally getting to you, $N.  Do not worry, I will not divulge your little secret -- lest the others think you're mad.$B$BGet some rest.  It'll do you good.","계속되는 전투에 신경이 쇠약해지셨나 봅니다, $n|1이여;여;. 걱정하지 마십시오, 방금 들은 얘기는 아무에게도 말하지 않겠습니다. 혹시 다른 사람이 이 얘길 들으면 그대를 미친 사람 취급할 테니까요.$B$B좀 쉬면 괜찮아질 겁니다."}
